# --- function 1: is_partial_role_mapping (function) lines 19-33 mode=ast ---
def is_partial_role_mapping(inp_roles: Dict, out_roles: Dict) -> bool:
    """
    Allow output to merge roles or drop roles, but not to map
    a single input role to multiple conflicting outputs.
    inp_roles/out_roles: role_id -> set of positions or list of positions
    """
    for role, positions in inp_roles.items():
        # What output-role this input-role "lands in"
        out_role_ids = {rid for rid, rpos in out_roles.items()
                        if any(p in (rpos if isinstance(rpos, (set, list)) else [rpos]) 
                               for p in (positions if isinstance(positions, (set, list)) else [positions]))}
        if len(out_role_ids) > 1:
            # One input role maps into several unrelated output roles → ambiguous
            return False
    return True

