# --- function 22: LargestBlobExtractOperator._largest_blob_mask (method) lines 679-725 mode=ast ---
def _largest_blob_mask(self, grid: np.ndarray) -> Optional[np.ndarray]:
    H, W = grid.shape
    visited = np.zeros((H, W), dtype=bool)
    blobs: List[List[Tuple[int, int]]] = []

    def neighbors(r, c):
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                yield nr, nc

    for r in range(H):
        for c in range(W):
            if visited[r, c]:
                continue
            if grid[r, c] == 0:
                visited[r, c] = True
                continue

            # BFS this blob
            color = grid[r, c]
            stack = [(r, c)]
            visited[r, c] = True
            blob = [(r, c)]

            while stack:
                rr, cc = stack.pop()
                for nr, nc in neighbors(rr, cc):
                    if visited[nr, nc]:
                        continue
                    if grid[nr, nc] == color:
                        visited[nr, nc] = True
                        stack.append((nr, nc))
                        blob.append((nr, nc))

            blobs.append(blob)

    if not blobs:
        return None

    # Choose largest blob (tie-break: first)
    largest_blob = max(blobs, key=len)
    mask = np.zeros((H, W), dtype=bool)
    for r, c in largest_blob:
        mask[r, c] = True

    return mask

# --- function 23: LargestBlobExtractOperator.apply (method) lines 727-735 mode=ast ---
def apply(self, input_grid: np.ndarray,
          params: Dict[str, Any]) -> np.ndarray:
    mask = self._largest_blob_mask(input_grid)
    if mask is None:
        # If no non-zero, just return zeros
        return np.zeros_like(input_grid)
    out = np.zeros_like(input_grid)
    out[mask] = input_grid[mask]
    return out

