def apply(self, input_grid: np.ndarray,
          params: Dict[str, Any]) -> np.ndarray:
    H, W = input_grid.shape
    k = int(params["k"])
    m = int(params["m"])
    pattern: Dict[Tuple[int, int], int] = params["pattern"]

    out = np.zeros_like(input_grid)
    for r in range(H):
        for c in range(W):
            key = (r % k, c % m)
            out[r, c] = pattern.get(key, 0)
    return out

