@property
def width(self) -> int:
    return self.bounding_box[3] - self.bounding_box[1] + 1

# --- function 2: Component.height (method) lines 38-40 mode=ast ---
@property
def height(self) -> int:
    return self.bounding_box[2] - self.bounding_box[0] + 1

