def __init__(self):
    self.debug = False

# --- function 4: CompEngine.find_components (method) lines 74-139 mode=ast ---
def find_components(self, grid: np.ndarray, 
                    color: Optional[int] = None,
                    connectivity: int = 4,
                    min_size: int = 1) -> List[Component]:
    """
    Find connected components in grid.

    Args:
        grid: Input grid
        color: If specified, find components of this color only
        connectivity: 4 or 8 (4: orthogonal, 8: diagonal)
        min_size: Minimum component size to include

    Returns:
        List of Component objects
    """
    H, W = grid.shape

    # Create binary mask for target pixels
    if color is not None:
        mask = (grid == color)
    else:
        # Find all non-background (assume 0 is background)
        mask = (grid != 0)

    if not np.any(mask):
        return []

    # Label connected components
    structure = None
    if connectivity == 4:
        structure = ndimage.generate_binary_structure(2, 1)  # 4-connectivity
    elif connectivity == 8:
        structure = ndimage.generate_binary_structure(2, 2)  # 8-connectivity
    else:
        raise ValueError(f"connectivity must be 4 or 8, got {connectivity}")

    labeled, num_features = ndimage.label(mask, structure=structure)

    # Extract component info
    components = []
    for label in range(1, num_features + 1):
        positions = set(zip(*np.where(labeled == label)))
        size = len(positions)

        if size < min_size:
            continue

        # Get bounding box
        rows, cols = zip(*positions)
        min_row, max_row = min(rows), max(rows)
        min_col, max_col = min(cols), max(cols)

        # Get color (most common in this component)
        component_colors = [grid[r, c] for r, c in positions]
        comp_color = max(set(component_colors), key=component_colors.count)

        components.append(Component(
            label=label,
            positions=positions,
            color=comp_color,
            bounding_box=(min_row, min_col, max_row, max_col),
            size=size
        ))

    return components

# --- function 5: CompEngine.largest_blob (method) lines 141-158 mode=ast ---
def largest_blob(self, grid: np.ndarray, 
                 color: Optional[int] = None,
                 connectivity: int = 4) -> Optional[Component]:
    """
    Find the largest connected component (blob).

    Args:
        grid: Input grid
        color: If specified, find largest blob of this color
        connectivity: 4 or 8

    Returns:
        Largest Component or None if no components found
    """
    components = self.find_components(grid, color=color, connectivity=connectivity)
    if not components:
        return None
    return max(components, key=lambda c: c.size)

# --- function 6: CompEngine.extract_region (method) lines 160-173 mode=ast ---
def extract_region(self, grid: np.ndarray, 
                   bounding_box: Tuple[int, int, int, int]) -> np.ndarray:
    """
    Extract rectangular region from grid.

    Args:
        grid: Input grid
        bounding_box: (min_row, min_col, max_row, max_col)

    Returns:
        Extracted region as new array
    """
    min_row, min_col, max_row, max_col = bounding_box
    return grid[min_row:max_row+1, min_col:max_col+1].copy()

# --- function 7: CompEngine.create_mask (method) lines 179-206 mode=ast ---
def create_mask(self, grid: np.ndarray,
                mask_type: str,
                mask_value: Optional[int] = None) -> np.ndarray:
    """
    Create binary mask from grid.

    Args:
        grid: Input grid
        mask_type: 'color', 'background', 'non_background'
        mask_value: For 'color' type, the color to mask

    Returns:
        Boolean mask (True = include in mask)
    """
    if mask_type == 'color':
        if mask_value is None:
            raise ValueError("mask_value required for 'color' mask_type")
        return grid == mask_value

    elif mask_type == 'background':
        # Assume 0 is background
        return grid == 0

    elif mask_type == 'non_background':
        return grid != 0

    else:
        raise ValueError(f"Unknown mask_type: {mask_type}")

# --- function 8: CompEngine.apply_mask (method) lines 208-224 mode=ast ---
def apply_mask(self, grid: np.ndarray, 
               mask: np.ndarray,
               fill_value: int = 0) -> np.ndarray:
    """
    Apply mask to grid (set masked pixels to fill_value).

    Args:
        grid: Input grid
        mask: Boolean mask (True = keep, False = fill)
        fill_value: Value for masked-out pixels

    Returns:
        Masked grid
    """
    result = grid.copy()
    result[~mask] = fill_value
    return result

# --- function 9: CompEngine.detect_masked_tiling (method) lines 230-316 mode=ast ---
def detect_masked_tiling(self, input_grid: np.ndarray,
                         output_grid: np.ndarray) -> Optional[MaskedTilingHypothesis]:
    """
    Detect if output is input tiled within a mask.

    Pattern: 007bbfb7, 5b6cbef5
    - Output is tiled version of input
    - Some regions are masked (preserved/zeroed based on input)

    Args:
        input_grid: Input grid
        output_grid: Output grid

    Returns:
        MaskedTilingHypothesis or None
    """
    H_in, W_in = input_grid.shape
    H_out, W_out = output_grid.shape

    # Check if output is size-multiple of input
    if H_out % H_in != 0 or W_out % W_in != 0:
        return None

    v_factor = H_out // H_in
    h_factor = W_out // W_in

    if v_factor == 1 and h_factor == 1:
        return None  # No tiling

    # Try simple tiling first
    simple_tiled = np.tile(input_grid, (v_factor, h_factor))

    # Check self-referential masking FIRST (5b6cbef5 pattern)
    # Mask out tiles where input has background (0)
    mask_tiled = np.tile(input_grid != 0, (v_factor, h_factor))
    masked_output = simple_tiled * mask_tiled

    if np.array_equal(output_grid, masked_output):
        # Check if mask actually differs from simple tiling
        # (i.e., input has background pixels that would be preserved in tiling)
        has_background = np.any(input_grid == 0)

        if has_background:
            # True self-referential masking
            return MaskedTilingHypothesis(
                mask_type='non_background',
                mask_value=0,
                tile_pattern=input_grid,
                tile_factor=(v_factor, h_factor),
                preserve_mask=True,
                confidence=1.0
            )
        else:
            # No background, so it's just simple tiling
            return MaskedTilingHypothesis(
                mask_type='none',
                mask_value=0,
                tile_pattern=input_grid,
                tile_factor=(v_factor, h_factor),
                preserve_mask=False,
                confidence=1.0
            )

    # Check if mask preserves specific color
    unique_colors = np.unique(input_grid)
    for color in unique_colors:
        if color == 0:
            continue  # Already tested background

        # Mask: tile only where input has this color
        mask_tiled = np.tile(input_grid == color, (v_factor, h_factor))
        masked_output = simple_tiled * mask_tiled

        if np.array_equal(output_grid, masked_output):
            return MaskedTilingHypothesis(
                mask_type='color',
                mask_value=color,
                tile_pattern=input_grid,
                tile_factor=(v_factor, h_factor),
                preserve_mask=True,
                confidence=1.0
            )

    # Check if different regions have different tiling
    # (More complex pattern - defer to future phase)

    return None

# --- function 10: CompEngine.apply_masked_tiling (method) lines 318-351 mode=ast ---
def apply_masked_tiling(self, input_grid: np.ndarray,
                        hypothesis: MaskedTilingHypothesis) -> np.ndarray:
    """
    Apply masked tiling transformation.

    Args:
        input_grid: Input grid to transform
        hypothesis: Tiling hypothesis with mask parameters

    Returns:
        Transformed grid
    """
    v_factor, h_factor = hypothesis.tile_factor

    # Create tiled grid
    tiled = np.tile(input_grid, (v_factor, h_factor))

    if hypothesis.mask_type == 'none':
        return tiled

    # Create mask
    if hypothesis.mask_type == 'non_background':
        mask = np.tile(input_grid != 0, (v_factor, h_factor))
    elif hypothesis.mask_type == 'color':
        mask = np.tile(input_grid == hypothesis.mask_value, (v_factor, h_factor))
    else:
        raise ValueError(f"Unsupported mask_type: {hypothesis.mask_type}")

    if hypothesis.preserve_mask:
        # Keep only masked regions
        return tiled * mask
    else:
        # Keep only non-masked regions
        return tiled * (~mask)

# --- function 11: CompEngine.analyze_training_examples (method) lines 357-382 mode=ast ---
def analyze_training_examples(self, train_pairs: List[Tuple[np.ndarray, np.ndarray]]) -> Optional[MaskedTilingHypothesis]:
    """
    Analyze multiple training examples to find consistent masked tiling pattern.

    Args:
        train_pairs: List of (input, output) pairs

    Returns:
        Consistent hypothesis or None
    """
    if not train_pairs:
        return None

    # Detect pattern from first example
    hypothesis = self.detect_masked_tiling(train_pairs[0][0], train_pairs[0][1])

    if hypothesis is None:
        return None

    # Validate on remaining examples
    for inp, out in train_pairs[1:]:
        predicted = self.apply_masked_tiling(inp, hypothesis)
        if not np.array_equal(predicted, out):
            return None  # Pattern doesn't generalize

    return hypothesis

