# --- function 15: test_masked_tiling_self_referential (function) lines 506-555 mode=ast ---
def test_masked_tiling_self_referential():
    """Test self-referential masked tiling (5b6cbef5 pattern)."""
    print("\n" + "="*60)
    print("TEST: detect_masked_tiling() - Self-Referential")
    print("="*60)

    engine = CompEngine()

    # Input with background (0) and foreground
    # Pattern where masking actually changes output
    input_grid = np.array([
        [1, 2],
        [3, 0]
    ])

    # Simple tile would give [[1,2,1,2],[3,0,3,0],[1,2,1,2],[3,0,3,0]]
    # But we want to zero out where input was 0 (bottom-right)
    # Expected: [[1,2,1,2],[3,0,3,0],[1,2,1,2],[3,0,3,0]]
    # With mask applied: [[1,2,1,2],[3,0,3,0],[1,2,1,2],[3,0,3,0]]
    # This STILL doesn't differ because 0*0=0!

    # Need a different approach: use input where 0s would conflict
    # Use a 3-color input
    input_grid = np.array([
        [1, 0, 2],
        [0, 3, 0],
        [4, 0, 5]
    ])

    # Tile it
    tiled = np.tile(input_grid, (2, 2))

    # Mask: zero out positions where input had 0
    # This creates a pattern different from simple tiling
    mask = np.tile(input_grid != 0, (2, 2))
    output_grid = tiled.copy()
    output_grid[~mask] = 0  # Explicitly zero out masked positions

    hypothesis = engine.detect_masked_tiling(input_grid, output_grid)
    assert hypothesis is not None, "Expected to detect self-referential tiling"
    assert hypothesis.mask_type == 'non_background', f"Expected mask_type 'non_background', got {hypothesis.mask_type}"
    assert hypothesis.preserve_mask == True, f"Expected preserve_mask True"
    print("✓ Self-referential tiling detected correctly")

    # Apply hypothesis
    predicted = engine.apply_masked_tiling(input_grid, hypothesis)
    assert np.array_equal(predicted, output_grid), "Applied tiling doesn't match expected output"
    print("✓ Applied self-referential tiling matches expected output")

    print("\n✓ ALL SELF-REFERENTIAL TILING TESTS PASSED")

