def reset(self):
    """Reset fusion state (for new match)."""
    self.feature_history.clear()
    self.resonance_state = np.zeros(3, dtype=np.float32)
    self.resonance_amplitudes = np.ones(3, dtype=np.float32)
    self.frames_fused = 0
    self.total_fusion_time = 0.0


