def _detect_crop_pattern(self, task_view: TaskView) -> List[Hypothesis]:
    """
    Detect cropping patterns: crop to object bbox, crop to content, etc.
    """
    hypotheses = []

    crop_to_largest = True
    crop_to_content = True

    for input_grid, output_grid in task_view.train_pairs:
        H_in, W_in = input_grid.shape
        H_out, W_out = output_grid.shape

        # Output must be smaller
        if H_out >= H_in or W_out >= W_in:
            crop_to_largest = False
            crop_to_content = False
            continue

        os_in = self.detect_objects_universal(input_grid)

        if len(os_in.objects) == 0:
            crop_to_largest = False
            crop_to_content = False
            continue

        # Check crop to largest object bbox
        largest = max(os_in.objects, key=lambda o: o.pixel_count)
        y0, x0, y1, x1 = largest.bbox

