# --- function 1: normalize_object_labels (function) lines 48-82 mode=ast ---
def normalize_object_labels(obj) -> DetectedObject:
    """
    Universal label normalization - reconciles old names to canonical spec.

    Apply this to EVERY object returned by ANY detection function.
    Raises ValueError if required canonical fields are missing after aliasing.
    """
    # Alias mappings: old_name -> canonical_name
    if hasattr(obj, 'center') and not hasattr(obj, 'centroid'):
        obj.centroid = obj.center

    if hasattr(obj, 'area') and not hasattr(obj, 'pixel_count'):
        obj.pixel_count = obj.area

    if hasattr(obj, 'shape_id') and not hasattr(obj, 'shape_signature'):
        obj.shape_signature = obj.shape_id

    if hasattr(obj, 'region') and not hasattr(obj, 'mask'):
        obj.mask = obj.region

    if hasattr(obj, 'size') and not hasattr(obj, 'radius'):
        # Fallback: estimate radius from size (will be refined with true Euclidean)
        obj.radius = np.sqrt(obj.size / np.pi)

    # Verify all required canonical fields exist
    required = [
        'object_id', 'color', 'mask', 'bbox', 'centroid', 'radius',
        'pixel_count', 'perimeter', 'shape_signature', 'sector'
    ]

    missing = [field for field in required if not hasattr(obj, field)]
    if missing:
        raise ValueError(f"Missing required fields after normalization: {missing}. Object: {obj}")

    return obj

# --- function 2: detect_objects (function) lines 85-187 mode=ast ---
def detect_objects(grid: np.ndarray) -> List[DetectedObject]:
    """
    8-connected component detection with exact lasso masks.

    Returns objects with full Euclidean geometry computed.
    This is the SINGLE SOURCE OF TRUTH for object detection.
    """
    if grid.size == 0:
        return []

    H, W = grid.shape
    visited = np.zeros((H, W), dtype=bool)
    objects = []
    next_id = 0

    for y in range(H):
        for x in range(W):
            color = grid[y, x]

            # Skip background or already visited
            if color == 0 or visited[y, x]:
                continue

            # BFS for 8-connected component
            queue = [(y, x)]
            pixels = []
            visited[y, x] = True

            while queue:
                cy, cx = queue.pop(0)
                pixels.append((cy, cx))

                # Check all 8 neighbors
                for dy in [-1, 0, 1]:
                    for dx in [-1, 0, 1]:
                        if dy == 0 and dx == 0:
                            continue

                        ny, nx = cy + dy, cx + dx

                        if 0 <= ny < H and 0 <= nx < W:
                            if not visited[ny, nx] and grid[ny, nx] == color:
                                visited[ny, nx] = True
                                queue.append((ny, nx))

            # Build exact boolean mask
            mask = np.zeros((H, W), dtype=bool)
            y0, x0 = H, W
            y1, x1 = 0, 0

            for py, px in pixels:
                mask[py, px] = True
                y0 = min(y0, py)
                x0 = min(x0, px)
                y1 = max(y1, py)
                x1 = max(x1, px)

            y1 += 1  # bbox is exclusive
            x1 += 1

            # Centroid - true geometric center (mean of all pixel coords)
            cy = np.mean([p[0] for p in pixels])
            cx = np.mean([p[1] for p in pixels])

            # Radius - max Euclidean distance from centroid to any pixel
            radius = 0.0
            for py, px in pixels:
                dist = np.sqrt((py - cy)**2 + (px - cx)**2)
                radius = max(radius, dist)

            # Perimeter - count pixels with at least one non-object 4-neighbor
            perimeter = 0
            for py, px in pixels:
                for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ny, nx = py + dy, px + dx
                    if not (0 <= ny < H and 0 <= nx < W) or not mask[ny, nx]:
                        perimeter += 1
                        break

            # Shape signature - hash of cropped mask for identity matching
            cropped_mask = mask[y0:y1, x0:x1]
            shape_signature = hash(cropped_mask.tobytes())

            # Sector placeholder (will be computed in build_object_space)
            sector = (0, 0)

            obj = DetectedObject(
                object_id=next_id,
                color=int(color),
                mask=mask,
                bbox=(y0, x0, y1, x1),
                centroid=(cy, cx),
                radius=radius,
                pixel_count=len(pixels),
                perimeter=perimeter,
                shape_signature=shape_signature,
                sector=sector
            )

            objects.append(obj)
            next_id += 1

    return objects

# --- function 3: build_object_space (function) lines 190-278 mode=ast ---
def build_object_space(objects: List[DetectedObject], H: int, W: int, 
                       num_sectors_y: int = 3, num_sectors_x: int = 3) -> ObjectSpace:
    """
    Build ObjectSpace with pre-computed Euclidean geometry.

    Computes:
    - Pairwise distances between all object centroids
    - Pairwise angles between all object centroids
    - Distance from each centroid to grid center
    - Sector grid occupancy

    Args:
        objects: List of DetectedObject
        H, W: Grid dimensions
        num_sectors_y, num_sectors_x: Sector grid size (default 3×3)

    Returns:
        ObjectSpace with all geometry pre-computed
    """
    N = len(objects)

    if N == 0:
        return ObjectSpace(
            H=H, W=W,
            objects=[],
            D=np.zeros((0, 0)),
            Theta=np.zeros((0, 0)),
            d_center=np.zeros(0),
            sectors={}
        )

    # Initialize arrays
    D = np.zeros((N, N))
    Theta = np.zeros((N, N))
    d_center = np.zeros(N)
    sectors = {}

    # Grid center
    center_y = (H - 1) / 2.0
    center_x = (W - 1) / 2.0

    # Sector dimensions
    sector_h = H / num_sectors_y
    sector_w = W / num_sectors_x

    # Compute per-object geometry
    for i, obj in enumerate(objects):
        cy, cx = obj.centroid

        # Distance from grid center
        d_center[i] = np.sqrt((cy - center_y)**2 + (cx - center_x)**2)

        # Sector index
        sy = int(cy / sector_h)
        sx = int(cx / sector_w)
        sy = max(0, min(sy, num_sectors_y - 1))
        sx = max(0, min(sx, num_sectors_x - 1))

        obj.sector = (sy, sx)

        if (sy, sx) not in sectors:
            sectors[(sy, sx)] = []
        sectors[(sy, sx)].append(obj.object_id)

    # Compute pairwise geometry
    for i in range(N):
        cy_i, cx_i = objects[i].centroid

        for j in range(N):
            cy_j, cx_j = objects[j].centroid

            dy = cy_j - cy_i
            dx = cx_j - cx_i

            # Distance
            D[i, j] = np.sqrt(dy**2 + dx**2)

            # Angle (radians)
            Theta[i, j] = np.arctan2(dy, dx)

    return ObjectSpace(
        H=H,
        W=W,
        objects=objects,
        D=D,
        Theta=Theta,
        d_center=d_center,
        sectors=sectors
    )

# --- function 4: check_sector_collision (function) lines 281-307 mode=ast ---
def check_sector_collision(objects: List[DetectedObject], H: int, W: int,
                          num_sectors_y: int = 3, num_sectors_x: int = 3) -> bool:
    """
    Check if any two objects rest in the same sector (collision rule).

    Objects may pass through each other during transforms,
    but final resting positions cannot share sectors.

    Returns:
        True if valid (no collisions), False if collision detected
    """
    sector_h = H / num_sectors_y
    sector_w = W / num_sectors_x

    occupied = {}

    for obj in objects:
        cy, cx = obj.centroid
        sy = max(0, min(int(cy / sector_h), num_sectors_y - 1))
        sx = max(0, min(int(cx / sector_w), num_sectors_x - 1))

        if (sy, sx) in occupied:
            return False  # Collision - two objects in same sector

        occupied[(sy, sx)] = obj.object_id

    return True


