# --- function 2: RelEngine.analyze (method) lines 39-61 mode=ast ---
def analyze(self, task_view: TaskView) -> List[Hypothesis]:
    """Analyze task for spatial relation transformations."""
    hypotheses = []

    # Check for move to corner
    corner_hyp = self._detect_move_to_corner(task_view)
    if corner_hyp:
        hypotheses.append(corner_hyp)

    # Check for alignment
    align_hyp = self._detect_align_to_object(task_view)
    if align_hyp:
        hypotheses.append(align_hyp)

    # Check for mirroring
    mirror_hyp = self._detect_mirror(task_view)
    if mirror_hyp:
        hypotheses.append(mirror_hyp)

    # Sort by confidence
    hypotheses.sort(key=lambda h: h.confidence, reverse=True)

    return hypotheses

# --- function 3: RelEngine._extract_objects (method) lines 63-93 mode=ast ---
def _extract_objects(self, grid: np.ndarray) -> List[ObjectInfo]:
    """Extract objects from grid."""
    labeled, num_features = label(grid != 0)
    objects = []

    for obj_id in range(1, num_features + 1):
        mask = (labeled == obj_id)
        coords = np.argwhere(mask)

        if len(coords) == 0:
            continue

        y0, x0 = coords.min(axis=0)
        y1, x1 = coords.max(axis=0)

        cy = (y0 + y1) / 2.0
        cx = (x0 + x1) / 2.0

        color = int(grid[mask][0])
        size = len(coords)

        objects.append(ObjectInfo(
            obj_id=obj_id,
            mask=mask,
            bbox=(y0, x0, y1 + 1, x1 + 1),
            center=(cy, cx),
            color=color,
            size=size
        ))

    return objects

# --- function 4: RelEngine._detect_move_to_corner (method) lines 95-160 mode=ast ---
def _detect_move_to_corner(self, task_view: TaskView) -> Optional[Hypothesis]:
    """Detect if largest object moves to a canonical corner."""

    target_corner = None

    for input_grid, output_grid in task_view.train_pairs:
        if input_grid.shape != output_grid.shape:
            return None

        h, w = output_grid.shape

        objs_in = self._extract_objects(input_grid)
        objs_out = self._extract_objects(output_grid)

        if len(objs_in) == 0 or len(objs_out) == 0:
            return None

        # Focus on largest object
        largest_in = max(objs_in, key=lambda o: o.size)
        largest_out = max(objs_out, key=lambda o: o.size)

        # Check if shapes match (same size)
        if largest_in.size != largest_out.size:
            return None

        # Determine which corner the output object is in
        y0, x0, y1, x1 = largest_out.bbox
        obj_h = y1 - y0
        obj_w = x1 - x0

        # Define corner positions
        corners = {
            'TL': (0, 0),
            'TR': (0, w - obj_w),
            'BL': (h - obj_h, 0),
            'BR': (h - obj_h, w - obj_w)
        }

        # Check which corner the object is closest to
        detected_corner = None
        for corner_name, (cy, cx) in corners.items():
            # Object is at corner if top-left bbox matches (within 1 pixel)
            if abs(y0 - cy) <= 1 and abs(x0 - cx) <= 1:
                detected_corner = corner_name
                break

        if detected_corner is None:
            return None

        # Check consistency across pairs
        if target_corner is None:
            target_corner = detected_corner
        elif target_corner != detected_corner:
            return None

    if target_corner:
        return Hypothesis(
            engine_name="REL",
            operation="MOVE_TO_CORNER",
            params={"corner": target_corner, "object": "largest"},
            confidence=0.9,
            dsl_program=f"REL:MOVE_TO_{target_corner}",
            explanation=f"Move largest object to {target_corner} corner"
        )

    return None

# --- function 5: RelEngine._detect_align_to_object (method) lines 162-233 mode=ast ---
def _detect_align_to_object(self, task_view: TaskView) -> Optional[Hypothesis]:
    """Detect if objects align to same row or column."""

    align_axis = None

    for input_grid, output_grid in task_view.train_pairs:
        if input_grid.shape != output_grid.shape:
            return None

        objs_in = self._extract_objects(input_grid)
        objs_out = self._extract_objects(output_grid)

        if len(objs_in) < 2 or len(objs_out) < 2:
            return None

        # Sort by size to identify anchor (largest stays, smaller moves)
        objs_in_sorted = sorted(objs_in, key=lambda o: o.size, reverse=True)
        objs_out_sorted = sorted(objs_out, key=lambda o: o.size, reverse=True)

        if len(objs_in_sorted) != len(objs_out_sorted):
            return None

        # Check if largest object (anchor) stays in same position
        anchor_in = objs_in_sorted[0]
        anchor_out = objs_out_sorted[0]

        cy_diff = abs(anchor_in.center[0] - anchor_out.center[0])
        cx_diff = abs(anchor_in.center[1] - anchor_out.center[1])

        if cy_diff > 2 or cx_diff > 2:
            # Anchor moved too much
            return None

        # Check if second object aligned with anchor
        if len(objs_in_sorted) >= 2:
            target_in = objs_in_sorted[1]
            target_out = objs_out_sorted[1]

            # Check row alignment (same y center)
            if abs(target_out.center[0] - anchor_out.center[0]) <= 1:
                if abs(target_in.center[0] - anchor_in.center[0]) > 2:
                    # Moved to align on row
                    detected_axis = "row"
                else:
                    detected_axis = None
            # Check column alignment (same x center)
            elif abs(target_out.center[1] - anchor_out.center[1]) <= 1:
                if abs(target_in.center[1] - anchor_in.center[1]) > 2:
                    # Moved to align on column
                    detected_axis = "col"
                else:
                    detected_axis = None
            else:
                detected_axis = None

            if detected_axis:
                if align_axis is None:
                    align_axis = detected_axis
                elif align_axis != detected_axis:
                    return None

    if align_axis:
        return Hypothesis(
            engine_name="REL",
            operation="ALIGN_TO_OBJECT",
            params={"anchor": "largest", "target": "other", "axis": align_axis},
            confidence=0.85,
            dsl_program=f"REL:ALIGN_{align_axis.upper()}",
            explanation=f"Align objects on same {align_axis}"
        )

    return None

# --- function 6: RelEngine._detect_mirror (method) lines 235-317 mode=ast ---
def _detect_mirror(self, task_view: TaskView) -> Optional[Hypothesis]:
    """Detect if objects are mirrored across axis."""

    mirror_axis = None

    for input_grid, output_grid in task_view.train_pairs:
        if input_grid.shape != output_grid.shape:
            return None

        h, w = input_grid.shape

        objs_in = self._extract_objects(input_grid)
        objs_out = self._extract_objects(output_grid)

        if len(objs_in) == 0 or len(objs_out) == 0:
            return None

        if len(objs_in) != len(objs_out):
            return None

        # Check if centers are mirrored
        # Vertical mirror: cx' = W - 1 - cx
        # Horizontal mirror: cy' = H - 1 - cy

        all_v_mirror = True
        all_h_mirror = True
        all_both_mirror = True

        for obj_in in objs_in:
            cy_in, cx_in = obj_in.center

            # Find matching object in output (by size/color)
            matching = [o for o in objs_out if o.size == obj_in.size and o.color == obj_in.color]
            if not matching:
                all_v_mirror = False
                all_h_mirror = False
                all_both_mirror = False
                break

            obj_out = matching[0]
            cy_out, cx_out = obj_out.center

            # Check vertical mirror
            expected_cx_v = w - 1 - cx_in
            if abs(cx_out - expected_cx_v) > 2 or abs(cy_out - cy_in) > 2:
                all_v_mirror = False

            # Check horizontal mirror
            expected_cy_h = h - 1 - cy_in
            if abs(cy_out - expected_cy_h) > 2 or abs(cx_out - cx_in) > 2:
                all_h_mirror = False

            # Check both (180 rotation)
            if abs(cy_out - expected_cy_h) > 2 or abs(cx_out - expected_cx_v) > 2:
                all_both_mirror = False

        detected_axis = None
        if all_v_mirror:
            detected_axis = "V"
        elif all_h_mirror:
            detected_axis = "H"
        elif all_both_mirror:
            detected_axis = "BOTH"

        if detected_axis is None:
            return None

        if mirror_axis is None:
            mirror_axis = detected_axis
        elif mirror_axis != detected_axis:
            return None

    if mirror_axis:
        return Hypothesis(
            engine_name="REL",
            operation="MIRROR",
            params={"axis": mirror_axis},
            confidence=0.9,
            dsl_program=f"REL:MIRROR_{mirror_axis}",
            explanation=f"Mirror objects across {mirror_axis} axis"
        )

    return None


