def analyze(self, task_view: TaskView) -> List[Hypothesis]:
    """Analyze task for shape-based transformations."""
    hypotheses = []

    # Check for solid ↔ outline transformations
    outline_hyp = self._detect_solid_outline_transform(task_view)
    if outline_hyp:
        hypotheses.append(outline_hyp)

    # Check for frame-based operations
    frame_hyp = self._detect_frame_operation(task_view)
    if frame_hyp:
        hypotheses.append(frame_hyp)

    # Check for line operations
    line_hyp = self._detect_line_operation(task_view)
    if line_hyp:
        hypotheses.append(line_hyp)

    # Sort by confidence
    hypotheses.sort(key=lambda h: h.confidence, reverse=True)

    return hypotheses

# --- function 3: ShapeEngine.analyze_grid (method) lines 65-105 mode=ast ---
def analyze_grid(self, grid: np.ndarray) -> List[ShapeHypothesis]:
    """Analyze a single grid and emit shape hypotheses."""
    shapes = []

    # Find connected components
    labeled, num_features = label(grid != 0)

    for comp_id in range(1, num_features + 1):
        mask = (labeled == comp_id)
        color = int(grid[mask][0])

        # Get bounding box
        coords = np.argwhere(mask)
        y0, x0 = coords.min(axis=0)
        y1, x1 = coords.max(axis=0)
        y1 += 1
        x1 += 1

        # Extract submask
        sub_mask = mask[y0:y1, x0:x1]
        h, w = sub_mask.shape

        # Classify shape
        shape_kind = self._classify_shape(sub_mask)

        if shape_kind:
            shapes.append(ShapeHypothesis(
                kind=shape_kind,
                bbox=(y0, x0, y1, x1),
                color=color,
                thickness=1,
                score=1.0,
                mask=mask
            ))

    # Check for grid-level frame
    frame_shape = self._detect_grid_frame(grid)
    if frame_shape:
        shapes.append(frame_shape)

    return shapes

# --- function 4: ShapeEngine._classify_shape (method) lines 107-139 mode=ast ---
def _classify_shape(self, sub_mask: np.ndarray) -> Optional[str]:
    """Classify a component's shape type."""
    h, w = sub_mask.shape
    total_pixels = np.count_nonzero(sub_mask)

    # Line detection
    if h == 1 and w > 1:
        return "line_h"
    if w == 1 and h > 1:
        return "line_v"

    # Rectangle detection
    if h < 2 or w < 2:
        return None

    # Check if solid rectangle
    if total_pixels == h * w:
        return "rect_solid"

    # Check if outline rectangle
    # Border should be all True, interior should be all False
    border_mask = np.zeros_like(sub_mask, dtype=bool)
    border_mask[0, :] = True
    border_mask[-1, :] = True
    border_mask[:, 0] = True
    border_mask[:, -1] = True

    interior_mask = ~border_mask

    if np.all(sub_mask[border_mask]) and np.count_nonzero(sub_mask[interior_mask]) == 0:
        return "rect_outline"

    return None

# --- function 5: ShapeEngine._detect_grid_frame (method) lines 141-179 mode=ast ---
def _detect_grid_frame(self, grid: np.ndarray) -> Optional[ShapeHypothesis]:
    """Detect if grid has a frame border."""
    h, w = grid.shape

    if h < 3 or w < 3:
        return None

    # Check 1-pixel border
    border_mask = np.zeros_like(grid, dtype=bool)
    border_mask[0, :] = True
    border_mask[-1, :] = True
    border_mask[:, 0] = True
    border_mask[:, -1] = True

    border_colors = set()
    interior_has_nonzero = False

    for i in range(h):
        for j in range(w):
            if border_mask[i, j]:
                if grid[i, j] != 0:
                    border_colors.add(int(grid[i, j]))
            else:
                if grid[i, j] != 0:
                    interior_has_nonzero = True

    # Frame if: single border color, different from interior
    if len(border_colors) == 1:
        frame_color = list(border_colors)[0]
        return ShapeHypothesis(
            kind="frame",
            bbox=(0, 0, h, w),
            color=frame_color,
            thickness=1,
            score=1.0,
            mask=border_mask
        )

    return None

# --- function 6: ShapeEngine._detect_solid_outline_transform (method) lines 181-238 mode=ast ---
def _detect_solid_outline_transform(self, task_view: TaskView) -> Optional[Hypothesis]:
    """Detect solid ↔ outline rectangle transformations."""

    # Check if all pairs follow solid → outline pattern
    solid_to_outline = True
    outline_to_solid = True

    for input_grid, output_grid in task_view.train_pairs:
        if input_grid.shape != output_grid.shape:
            solid_to_outline = False
            outline_to_solid = False
            break

        shapes_in = self.analyze_grid(input_grid)
        shapes_out = self.analyze_grid(output_grid)

        # Filter to rectangles only
        rects_in = [s for s in shapes_in if s.kind in ["rect_solid", "rect_outline"]]
        rects_out = [s for s in shapes_out if s.kind in ["rect_solid", "rect_outline"]]

        if len(rects_in) != len(rects_out):
            solid_to_outline = False
            outline_to_solid = False
            continue

        # Check solid → outline
        for rect_in, rect_out in zip(rects_in, rects_out):
            if rect_in.bbox != rect_out.bbox:
                solid_to_outline = False
                outline_to_solid = False
                break

            if rect_in.kind == "rect_solid" and rect_out.kind != "rect_outline":
                solid_to_outline = False
            if rect_in.kind == "rect_outline" and rect_out.kind != "rect_solid":
                outline_to_solid = False

    if solid_to_outline:
        return Hypothesis(
            engine_name="SHAPE",
            operation="SOLID_TO_OUTLINE",
            params={"mode": "all_rects"},
            confidence=0.95,
            dsl_program="SHAPE:SOLID_TO_OUTLINE",
            explanation="Convert solid rectangles to outlines"
        )

    if outline_to_solid:
        return Hypothesis(
            engine_name="SHAPE",
            operation="OUTLINE_TO_SOLID",
            params={"mode": "all_rects"},
            confidence=0.95,
            dsl_program="SHAPE:OUTLINE_TO_SOLID",
            explanation="Convert outline rectangles to solid"
        )

    return None

# --- function 7: ShapeEngine._detect_frame_operation (method) lines 240-277 mode=ast ---
def _detect_frame_operation(self, task_view: TaskView) -> Optional[Hypothesis]:
    """Detect frame-based operations."""

    # Check if all pairs have frames
    all_have_frame = True
    frame_preserved = True
    interior_operation = None

    for input_grid, output_grid in task_view.train_pairs:
        if input_grid.shape != output_grid.shape:
            all_have_frame = False
            break

        shapes_in = self.analyze_grid(input_grid)
        shapes_out = self.analyze_grid(output_grid)

        frame_in = next((s for s in shapes_in if s.kind == "frame"), None)
        frame_out = next((s for s in shapes_out if s.kind == "frame"), None)

        if not frame_in or not frame_out:
            all_have_frame = False
            break

        if frame_in.color != frame_out.color:
            frame_preserved = False

    if all_have_frame and frame_preserved:
        # Frame is preserved - operation is on interior
        return Hypothesis(
            engine_name="SHAPE",
            operation="FRAME_INTERIOR",
            params={"mode": "preserve_frame"},
            confidence=0.85,
            dsl_program="SHAPE:FRAME_INTERIOR",
            explanation="Preserve frame, operate on interior"
        )

    return None

# --- function 8: ShapeEngine._detect_line_operation (method) lines 279-324 mode=ast ---
def _detect_line_operation(self, task_view: TaskView) -> Optional[Hypothesis]:
    """Detect line-based operations."""

    # Check for line recoloring
    all_have_lines = True
    lines_recolored = True

    for input_grid, output_grid in task_view.train_pairs:
        if input_grid.shape != output_grid.shape:
            all_have_lines = False
            break

        shapes_in = self.analyze_grid(input_grid)
        shapes_out = self.analyze_grid(output_grid)

        lines_in = [s for s in shapes_in if s.kind in ["line_h", "line_v"]]
        lines_out = [s for s in shapes_out if s.kind in ["line_h", "line_v"]]

        if len(lines_in) == 0:
            all_have_lines = False
            break

        if len(lines_in) != len(lines_out):
            lines_recolored = False
            continue

        # Check if lines moved or just recolored
        for line_in, line_out in zip(lines_in, lines_out):
            if line_in.bbox != line_out.bbox:
                lines_recolored = False
                break
            if line_in.color == line_out.color:
                lines_recolored = False
                break

    if all_have_lines and lines_recolored:
        return Hypothesis(
            engine_name="SHAPE",
            operation="RECOLOR_LINES",
            params={"mode": "all_lines"},
            confidence=0.85,
            dsl_program="SHAPE:RECOLOR_LINES",
            explanation="Recolor all lines"
        )

    return None


