# --- function 1: ProductionSolver.__init__ (method) lines 30-45 mode=ast ---
def __init__(self, operators):
    """
    Initialize production solver with both layers.

    Args:
        operators: List of ArcOperator instances (should be 29 operators)
    """
    self.operators = operators
    self.baseline_solver = BaselineSolver(operators)
    self.composition_solver = CompositionSolver(operators)

    self.stats = {
        "baseline_solves": 0,
        "composition_solves": 0,
        "total_attempts": 0
    }

# --- function 2: ProductionSolver.solve (method) lines 47-78 mode=ast ---
def solve(self, task: Dict) -> Optional[Dict]:
    """
    Solve ARC task using layered architecture.

    Execution order (IMMUTABLE):
      1. Try Layer 0: Baseline solver
      2. If fails, try Layer 1: Composition solver
      3. Return first successful result

    Args:
        task: ARC task dict with 'train' and 'test' keys

    Returns:
        Solution dict with rule_type, operators, and test_outputs
        or None if no solution found
    """
    self.stats["total_attempts"] += 1

    # Layer 0: Baseline solver (SACRED - runs first always)
    baseline_result = self.baseline_solver.solve(task)
    if baseline_result is not None:
        self.stats["baseline_solves"] += 1
        return baseline_result

    # Layer 1: Composition solver (only if baseline failed)
    composition_result = self.composition_solver.solve(task)
    if composition_result is not None:
        self.stats["composition_solves"] += 1
        return composition_result

    # No solution found
    return None

# --- function 3: ProductionSolver.get_stats (method) lines 80-82 mode=ast ---
def get_stats(self) -> Dict:
    """Get solver statistics."""
    return self.stats.copy()

# --- function 4: ProductionSolver.reset_stats (method) lines 84-90 mode=ast ---
def reset_stats(self):
    """Reset solver statistics."""
    self.stats = {
        "baseline_solves": 0,
        "composition_solves": 0,
        "total_attempts": 0
    }


