def iter_records(self):
    """Iterate all records in store order. Generator."""
    if self._data is None:
        return
    pos = HEADER_SIZE
    end = len(self._data)
    while pos < end:
        rec, next_pos = LexiconRecord.from_bytes(self._data, pos)
        yield rec
        pos = next_pos

