@property
def unresolved(self) -> bool:
    return bool(self.flags & 0x01)

# --- function 41: CitationRecord.auto_generated (method) lines 929-931 mode=ast ---
@property
def auto_generated(self) -> bool:
    return bool(self.flags & 0x02)

