def get(self, cite_id: str) -> Optional[CitationRecord]:
    """Read a single record by cite_id."""
    loc = self._index.get(cite_id)
    if loc is None:
        return None
    offset, length = loc
    abs_offset = HEADER_SIZE + offset
    rec, _ = CitationRecord.from_bytes(self._data, abs_offset)
    return rec

