def _resolve(self, anchor: str):
    """Resolve word to binary cell."""
    self._ensure_loaded()
    cell = self._store.read_cell(anchor)
    if cell:
        return cell
    sym = self._store.resolve_word(anchor.lower())
    if sym:
        return self._store.read_cell(sym)
    return None

