@router.get("/cascade")
async def cloud_cascade(
    anchor: str,
    hops: int = 2,
    top_k: int = 6,
    decay: float = 0.75,
    output: str = "discovery",
):
    """Cloud Cascade — recursive context cloud traversal.

    Walk the evidence graph from a root anchor, tracking provenance
    at every edge. Returns discovery (what was reached) or audit
    (how it got there) output.

    Args:
        anchor: Root anchor word to start traversal from
        hops: Maximum traversal depth (2=practical, 3=experimental)
        top_k: Top-K neighbors to expand at each hop
        decay: Hop decay factor for cumulative path scoring
        output: "discovery" (reached anchors) or "audit" (full path chains) or "both"
    """
    from cascade_616.core.engine import CascadeEngine
    engine = CascadeEngine()

    if not engine._store:
        return {"error": "Evidence store not loaded"}

    result = await asyncio.to_thread(
        run_cascade,
        engine._store,
        anchor,
        max_hops=min(hops, 3),
        top_k=min(top_k, 20),
        hop_decay=max(0.1, min(decay, 1.0)),
    )

    resp = {
        "root": result.root_word,
        "root_hex": result.root_hex,
        "max_hops": result.max_hops,
        "top_k": result.top_k,
        "hop_decay": result.hop_decay,
    }

    if output in ("discovery", "both"):
        resp["discovery"] = result.discovery_output()
    if output in ("audit", "both"):
        resp["audit"] = result.audit_output()

    return resp


