def save_profile(self, payload: Dict[str, Any]) -> Dict[str, Any]:
    with self._lock:
        self.ensure_initialized()
        if not self._feature_enabled("profile"):
            return self._feature_disabled("profile")

        display_name = self._sanitize_text(
            payload.get("display_name", ""),
            max_len=80,
        )
        bio = self._sanitize_text(payload.get("bio", ""), max_len=2000)
        interests = self._sanitize_text_list(
            payload.get("interests", []),
            max_items=32,
            max_len=64,
        )
        top_3_needs = self._sanitize_text_list(
            payload.get("top_3_needs", []),
            max_items=3,
            max_len=64,
        )
        featured_plugins = self._sanitize_plugin_ids(
            payload.get("featured_plugins", []),
            max_items=64,
        )
        if featured_plugins is None:
            return self._validation_error(
                "featured_plugins contains invalid plugin_id values",
                field="featured_plugins",
            )

