def _sanitize_text(self, value: Any, *, max_len: int) -> str:
    if value is None:
        return ""
    text = str(value).strip()
    if len(text) > max_len:
        return text[:max_len]
    return text

# --- function 20: ClearboxAISocialEngine._sanitize_text_list (method) lines 439-453 mode=ast ---
def _sanitize_text_list(
    self,
    values: Any,
    *,
    max_items: int,
    max_len: int,
) -> List[str]:
    if not isinstance(values, list):
        return []
    out: List[str] = []
    for item in values[:max_items]:
        text = self._sanitize_text(item, max_len=max_len)
        if text:
            out.append(text)
    return out

