# --- function 1: _fmt_count (function) lines 21-32 mode=ast ---
def _fmt_count(n: Any) -> str:
    if n is None:
        return "0"
    try:
        n = int(n)
    except (TypeError, ValueError):
        return str(n)
    if n >= 1_000_000:
        return f"{n / 1e6:.1f}M"
    if n >= 1_000:
        return f"{n / 1e3:.1f}K"
    return str(n)

