def arxiv_search(
    self,
    query: str,
    category: str = "",
    sort: str = "submittedDate",
    max_results: int = 10,
) -> List[Dict[str, Any]]:
    """Search arXiv papers. Returns list of paper dicts."""
    if category and query:
        sq = f"all:{urllib.parse.quote(query)}+AND+cat:{category}"
    elif category:
        sq = f"cat:{category}"
    elif query:
        sq = f"all:{urllib.parse.quote(query)}"
    else:
        sq = "cat:cs.AI"

    url = (
        f"https://export.arxiv.org/api/query"
        f"?search_query={sq}"
        f"&start=0&max_results={max_results}"
        f"&sortBy={sort}&sortOrder=descending"
    )
    try:
        data = self._get(url)
    except Exception as e:
        logger.error("arXiv search error: %s", e)
        return [{"error": str(e)}]

    return self._parse_arxiv_xml(data)

# --- function 8: ResearchEngine.arxiv_abstract (method) lines 94-104 mode=ast ---
def arxiv_abstract(self, arxiv_id: str) -> Dict[str, Any]:
    """Fetch a single arXiv paper by ID."""
    aid = arxiv_id.replace("https://arxiv.org/abs/", "").replace("http://arxiv.org/abs/", "").strip()
    url = f"https://export.arxiv.org/api/query?id_list={urllib.parse.quote(aid)}"
    try:
        data = self._get(url)
    except Exception as e:
        return {"error": str(e)}

    papers = self._parse_arxiv_xml(data)
    return papers[0] if papers else {"error": "not_found", "id": arxiv_id}

# --- function 9: ResearchEngine._parse_arxiv_xml (method) lines 106-134 mode=ast ---
def _parse_arxiv_xml(self, data: bytes) -> List[Dict[str, Any]]:
    root = ET.fromstring(data)
    papers: List[Dict[str, Any]] = []
    for entry in root.findall(f"{{{_ATOM_NS}}}entry"):
        pdf_url = ""
        for link in entry.findall(f"{{{_ATOM_NS}}}link"):
            if link.get("title") == "pdf":
                pdf_url = link.get("href", "")

        cats = [
            c.get("term", "")
            for c in entry.findall(f"{{{_ARXIV_NS}}}primary_category")
            + entry.findall(f"{{{_ATOM_NS}}}category")
        ]

        papers.append({
            "id": (entry.findtext(f"{{{_ATOM_NS}}}id") or "").strip(),
            "title": " ".join((entry.findtext(f"{{{_ATOM_NS}}}title") or "").split()),
            "authors": ", ".join(
                a.findtext(f"{{{_ATOM_NS}}}name") or ""
                for a in entry.findall(f"{{{_ATOM_NS}}}author")
            ),
            "abstract": (entry.findtext(f"{{{_ATOM_NS}}}summary") or "").strip(),
            "published": (entry.findtext(f"{{{_ATOM_NS}}}published") or "")[:10],
            "categories": ", ".join(dict.fromkeys(cats)),  # dedupe, preserve order
            "pdf_url": pdf_url,
            "source": "arxiv",
        })
    return papers

# --- function 10: ResearchEngine.pubmed_search (method) lines 140-194 mode=ast ---
def pubmed_search(
    self,
    query: str,
    article_type: str = "",
    sort: str = "relevance",
    max_results: int = 10,
) -> List[Dict[str, Any]]:
    """Search PubMed articles. Returns list of article dicts."""
    term = query
    if article_type:
        term += f"+AND+{article_type}[pt]"

    try:
        search_url = (
            f"{self._PUBMED_BASE}/esearch.fcgi"
            f"?db=pubmed&term={urllib.parse.quote(term)}"
            f"&retmax={max_results}&sort={sort}&retmode=json"
        )
        search_data = self._get_json(search_url)
    except Exception as e:
        return [{"error": str(e)}]

    ids: List[str] = search_data.get("esearchresult", {}).get("idlist", [])
    if not ids:
        return []

    try:
        sum_url = (
            f"{self._PUBMED_BASE}/esummary.fcgi"
            f"?db=pubmed&id={','.join(ids)}&retmode=json"
        )
        sum_data = self._get_json(sum_url)
    except Exception as e:
        return [{"error": str(e)}]

    result_map = sum_data.get("result", {})
    articles: List[Dict[str, Any]] = []
    for pmid in ids:
        r = result_map.get(pmid, {})
        pmcid = next(
            (a["value"] for a in r.get("articleids", []) if a.get("idtype") == "pmc"),
            "",
        )
        articles.append({
            "pmid": pmid,
            "title": r.get("title", ""),
            "authors": ", ".join(a.get("name", "") for a in r.get("authors", [])),
            "journal": r.get("source", ""),
            "pubdate": r.get("pubdate", ""),
            "pmcid": pmcid,
            "pubmed_url": f"https://pubmed.ncbi.nlm.nih.gov/{pmid}/",
            "pmc_url": f"https://www.ncbi.nlm.nih.gov/pmc/articles/{pmcid}/" if pmcid else "",
            "source": "pubmed",
        })
    return articles

# --- function 11: ResearchEngine.pubmed_abstract (method) lines 196-207 mode=ast ---
def pubmed_abstract(self, pmid: str) -> Dict[str, Any]:
    """Fetch full abstract text for a PubMed article."""
    try:
        url = (
            f"{self._PUBMED_BASE}/efetch.fcgi"
            f"?db=pubmed&id={urllib.parse.quote(pmid)}"
            f"&rettype=abstract&retmode=text"
        )
        text = self._get(url).decode("utf-8", errors="replace")
    except Exception as e:
        return {"error": str(e), "pmid": pmid}
    return {"pmid": pmid, "abstract_text": text, "source": "pubmed"}

# --- function 12: ResearchEngine.hf_search (method) lines 214-255 mode=ast ---
def hf_search(
    self,
    query: str = "",
    task: str = "",
    sort: str = "trending",
    max_results: int = 10,
    token: str = "",
) -> List[Dict[str, Any]]:
    """Search HuggingFace datasets. Returns list of dataset dicts."""
    url = f"{self._HF_API}/datasets?limit={max_results}&full=true"
    if query:
        url += f"&search={urllib.parse.quote(query)}"
    if task:
        url += f"&task_categories={urllib.parse.quote(task)}"
    _sort_map = {
        "downloads": "downloads&direction=-1",
        "likes": "likes&direction=-1",
        "created": "createdAt&direction=-1",
    }
    if sort in _sort_map:
        url += f"&sort={_sort_map[sort]}"

    try:
        data = self._get_json(url, self._hf_headers(token))
    except Exception as e:
        return [{"error": str(e)}]

    if not isinstance(data, list):
        return []

    return [
        {
            "id": x.get("id", ""),
            "description": (x.get("description") or "")[:400],
            "downloads": _fmt_count(x.get("downloads")),
            "likes": _fmt_count(x.get("likes")),
            "modified": x.get("lastModified", ""),
            "hf_url": f"https://huggingface.co/datasets/{x.get('id', '')}",
            "source": "huggingface",
        }
        for x in data
    ]

