def revoke(self, channel: str, channel_user_id: str) -> bool:
    """Revoke a pairing. Returns True if it existed."""
    key = self._key(channel, channel_user_id)
    if key in self._pairs:
        del self._pairs[key]
        self._save()
        logger.info("Revoked pairing for %s", key[:20])
        return True
    return False

