def health(self) -> Dict[str, Any]:
    """Basic stats."""
    return {
        "ok": self.header is not None,
        "records": self.count(),
        "coords": len(self._coord_index),
        "receipts": len(self._rcpt_index),
        "header": self.header.describe() if self.header else None,
    }

