def cancel(self, job_id: str) -> Optional[JobRecord]:
    with self._lock:
        record = self._jobs.get(job_id)
        if not record:
            return None
        record.cancel_requested = True
        record.status = "cancelling" if record.status == "running" else "cancelled"
        record.updated_at = time.time()
        return record

