def __init__(self):
    from core.chat_packs.config import load_config

    self._config = load_config()
    try:
        from security.data_paths import CHAT_PACKS_PACKS_DIR, CHAT_PACKS_SESSIONS_DIR
        self._packs_dir = CHAT_PACKS_PACKS_DIR
        self._sessions_dir = CHAT_PACKS_SESSIONS_DIR
    except ImportError:
        self._packs_dir = Path("chat_packs/packs")
        self._sessions_dir = Path("chat_packs/sessions")

    self._packs: Dict[str, Dict] = {}
    self._scan_packs()
    logger.info("ChatPackEngine: %d packs loaded from %s", len(self._packs), self._packs_dir)

# --- function 2: ChatPackEngine._iter_pack_dirs (method) lines 43-56 mode=ast ---
def _iter_pack_dirs(self):
    """Yield candidate pack directories recursively under the packs root."""
    if not self._packs_dir.exists():
        return
    seen: set[Path] = set()
    for meta_path in self._packs_dir.rglob("metadata.json"):
        entry = meta_path.parent
        if entry in seen or not entry.is_dir():
            continue
        # A valid pack must still have the required runtime files.
        if not all((entry / req_file).exists() for req_file in _REQUIRED_FILES):
            continue
        seen.add(entry)
        yield entry

# --- function 3: ChatPackEngine._scan_packs (method) lines 58-104 mode=ast ---
def _scan_packs(self) -> None:
    """Scan packs directory, load metadata for each valid pack."""
    self._packs.clear()
    for entry in self._iter_pack_dirs() or []:
        meta_path = entry / "metadata.json"
        try:
            with open(meta_path, "r", encoding="utf-8-sig") as f:
                meta = json.load(f)
            pack_id = meta.get("pack_id", "")
            if not pack_id:
                continue

            # Parse sections and questions for counts
            lesson_path = entry / "lesson.txt"
            lesson_text = ""
            if lesson_path.exists():
                lesson_text = lesson_path.read_text(encoding="utf-8-sig")
            sections = self.parse_sections(lesson_text)

            questions_path = entry / "questions.json"
            questions = []
            if questions_path.exists():
                try:
                    questions = json.loads(questions_path.read_text(encoding="utf-8-sig"))
                except json.JSONDecodeError:
                    pass

            readme_path = entry / "README.txt"
            readme = ""
            if readme_path.exists():
                readme = readme_path.read_text(encoding="utf-8-sig")

            self._packs[pack_id] = {
                "pack_id": pack_id,
                "title": meta.get("title", entry.name),
                "version": meta.get("version", "0.1"),
                "mode": meta.get("mode", "stepwise"),
                "tags": meta.get("tags", []),
                "difficulty": meta.get("difficulty", ""),
                "folder": str(entry),
                "sections": sections,
                "questions": questions if isinstance(questions, list) else [],
                "readme": readme,
                "has_assets": (entry / "assets").is_dir() and any((entry / "assets").iterdir()),
            }
        except Exception as e:
            logger.warning("Failed to load pack from %s: %s", entry, e)

# --- function 4: ChatPackEngine.rescan (method) lines 106-109 mode=ast ---
def rescan(self) -> int:
    """Rescan the packs directory and return the installed pack count."""
    self._scan_packs()
    return len(self._packs)

