def start_session(self, pack_id: str, model: str = "") -> Optional[Dict]:
    """Create a new session for a pack. Returns session dict or None."""
    pack = self._packs.get(pack_id)
    if not pack:
        return None

    session_id = uuid4().hex[:12]
    now = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

    session = {
        "session_id": session_id,
        "pack_id": pack_id,
        "model": model or self._config.get("default_model", "qwen2.5:7b-instruct"),
        "phase": "lesson",
        "section_index": 0,
        "question_index": 0,
        "total_sections": len(pack["sections"]),
        "total_questions": len(pack["questions"]),
        "scores": [],
        "started_utc": now,
        "updated_utc": now,
    }

    self._save_session(session_id, session)
    return session

