# --- function 2: HelpSystemEngine._load_content (method) lines 25-46 mode=ast ---
def _load_content(self) -> None:
    """Load help_content.json from the core help content directory."""
    from core.help_system.config import load_config

    config = load_config()
    content_path = Path(config["content_path"])

    if not content_path.exists():
        logger.warning("Help content file not found: %s", content_path)
        return

    try:
        with open(content_path, "r", encoding="utf-8") as f:
            self._content = json.load(f)
        self._build_search_index()
        logger.info(
            "Help System loaded %d entries from %s",
            len(self._content),
            content_path,
        )
    except Exception as e:
        logger.error("Failed to load help content: %s", e, exc_info=True)

# --- function 3: HelpSystemEngine._build_search_index (method) lines 48-67 mode=ast ---
def _build_search_index(self) -> None:
    """Build a flat search index from all content for text search."""
    self._search_index = []
    for help_id, entry in self._content.items():
        layer1 = entry.get("layer1", {})
        searchable = " ".join([
            help_id,
            entry.get("label", ""),
            entry.get("category", ""),
            layer1.get("what", ""),
            layer1.get("why", ""),
            layer1.get("consequence", ""),
            layer1.get("avoid", ""),
        ]).lower()
        self._search_index.append({
            "help_id": help_id,
            "label": entry.get("label", ""),
            "category": entry.get("category", ""),
            "searchable": searchable,
        })

# --- function 4: HelpSystemEngine.get_entry (method) lines 69-71 mode=ast ---
def get_entry(self, help_id: str) -> Optional[Dict[str, Any]]:
    """Return the full help entry for a given ID, or None."""
    return self._content.get(help_id)

# --- function 5: HelpSystemEngine.search (method) lines 73-88 mode=ast ---
def search(self, query: str) -> List[Dict[str, Any]]:
    """Search help content. Returns list of {help_id, label, category, snippet}."""
    q = query.lower()
    results = []
    for item in self._search_index:
        if q in item["searchable"]:
            entry = self._content.get(item["help_id"], {})
            layer1 = entry.get("layer1", {})
            snippet = layer1.get("what", "")[:120]
            results.append({
                "help_id": item["help_id"],
                "label": item["label"],
                "category": item["category"],
                "snippet": snippet,
            })
    return results

# --- function 6: HelpSystemEngine._catalog_row (method) lines 90-108 mode=ast ---
def _catalog_row(self, help_id: str, entry: Dict[str, Any]) -> Dict[str, Any]:
    layer1 = entry.get("layer1", {}) or {}
    snippet = (
        layer1.get("what")
        or layer1.get("why")
        or layer1.get("consequence")
        or ""
    )[:180]
    return {
        "help_id": help_id,
        "label": entry.get("label", ""),
        "category": entry.get("category", ""),
        "icon": entry.get("icon", ""),
        "snippet": snippet,
        "difficulty": entry.get("difficulty", ""),
        "tutorial_available": entry.get("tutorial_available", False),
        "has_layer2": bool(entry.get("layer2")),
        "has_layer3": bool(entry.get("layer3")),
    }

