def list_ids(self) -> List[Dict[str, Any]]:
    """Return all help IDs with summary fields for catalog browsing."""
    return [
        self._catalog_row(hid, entry)
        for hid, entry in sorted(self._content.items())
    ]

# --- function 8: HelpSystemEngine.build_assistant_context (method) lines 117-173 mode=ast ---
def build_assistant_context(
    self,
    *,
    query: str,
    focus_help_id: Optional[str] = None,
    limit: int = 6,
) -> Dict[str, Any]:
    """Build deterministic help-only context for the LLM assistant."""
    results: List[Dict[str, Any]] = []
    seen: set[str] = set()

    def add_entry(help_id: str) -> None:
        if not help_id or help_id in seen:
            return
        entry = self.get_entry(help_id)
        if not entry:
            return
        seen.add(help_id)
        results.append(
            {
                "help_id": help_id,
                "label": entry.get("label", ""),
                "category": entry.get("category", ""),
                "difficulty": entry.get("difficulty", ""),
                "tutorial_available": entry.get("tutorial_available", False),
                "layer1": entry.get("layer1"),
                "layer2": entry.get("layer2"),
                "layer3": entry.get("layer3"),
            }
        )

    if focus_help_id:
        add_entry(focus_help_id)

    for match in self.search(query or "")[: max(limit, 0)]:
        add_entry(match.get("help_id", ""))
        if len(results) >= limit:
            break

    if focus_help_id and len(results) < limit:
        focus = self.get_entry(focus_help_id)
        focus_cat = (focus or {}).get("category")
        if focus_cat:
            for row in self.list_ids():
                if row.get("category") != focus_cat:
                    continue
                add_entry(str(row.get("help_id", "")))
                if len(results) >= limit:
                    break

    return {
        "focus_help_id": focus_help_id,
        "query": query,
        "total_known_ids": len(self._content),
        "categories": self.get_stats().get("categories", {}),
        "entries": results[:limit],
    }

# --- function 9: HelpSystemEngine.get_stats (method) lines 175-191 mode=ast ---
def get_stats(self) -> Dict[str, Any]:
    """Return stats about the loaded content."""
    categories: Dict[str, int] = {}
    layers = {"layer1": 0, "layer2": 0, "layer3": 0}

    for entry in self._content.values():
        cat = entry.get("category", "Uncategorized")
        categories[cat] = categories.get(cat, 0) + 1
        for layer_key in ("layer1", "layer2", "layer3"):
            if entry.get(layer_key):
                layers[layer_key] += 1

    return {
        "total_ids": len(self._content),
        "categories": categories,
        "layers_coverage": layers,
    }


