# --- function 9: SpellChecker._damerau_levenshtein (method) lines 214-247 mode=ast ---
@staticmethod
def _damerau_levenshtein(s: str, t: str) -> int:
    """Optimal-string-alignment (restricted edit) distance."""
    len_s = len(s)
    len_t = len(t)
    # Fast paths
    if s == t:
        return 0
    if len_s == 0:
        return len_t
    if len_t == 0:
        return len_s

    # DP matrix
    d = [[0] * (len_t + 1) for _ in range(len_s + 1)]
    for i in range(len_s + 1):
        d[i][0] = i
    for j in range(len_t + 1):
        d[0][j] = j

    for i in range(1, len_s + 1):
        for j in range(1, len_t + 1):
            cost = 0 if s[i - 1] == t[j - 1] else 1
            d[i][j] = min(
                d[i - 1][j] + 1,       # deletion
                d[i][j - 1] + 1,       # insertion
                d[i - 1][j - 1] + cost,  # substitution
            )
            # Transposition
            if (i > 1 and j > 1
                    and s[i - 1] == t[j - 2]
                    and s[i - 2] == t[j - 1]):
                d[i][j] = min(d[i][j], d[i - 2][j - 2] + cost)
    return d[len_s][len_t]

# --- function 10: SpellChecker._is_adjacent_transposition (method) lines 249-258 mode=ast ---
@staticmethod
def _is_adjacent_transposition(s: str, t: str) -> bool:
    """True if *s* and *t* differ only by a swap of two adjacent chars."""
    if len(s) != len(t):
        return False
    diffs = [i for i in range(len(s)) if s[i] != t[i]]
    return (len(diffs) == 2
            and diffs[1] - diffs[0] == 1
            and s[diffs[0]] == t[diffs[1]]
            and s[diffs[1]] == t[diffs[0]])

# --- function 11: SpellChecker._shared_bigrams (method) lines 260-267 mode=ast ---
@staticmethod
def _shared_bigrams(s: str, t: str) -> int:
    """Count of character bigrams shared between *s* and *t*."""
    if len(s) < 2 or len(t) < 2:
        return 0
    s_bi = {s[i:i + 2] for i in range(len(s) - 1)}
    t_bi = {t[i:i + 2] for i in range(len(t) - 1)}
    return len(s_bi & t_bi)

