def _load_all_raw() -> dict:
    if not INFERENCE_PROFILES_PATH.exists():
        return {}
    try:
        return secure_json_load(INFERENCE_PROFILES_PATH)
    except Exception:
        return {}

# --- function 2: _save_all_raw (function) lines 29-30 mode=ast ---
def _save_all_raw(data: dict) -> None:
    secure_json_dump(INFERENCE_PROFILES_PATH, data)

# --- function 3: load_all_profiles (function) lines 33-35 mode=ast ---
def load_all_profiles() -> dict:
    """Return all saved per-model inference profiles."""
    return _load_all_raw()

# --- function 4: load_profile (function) lines 38-40 mode=ast ---
def load_profile(model: str) -> dict | None:
    """Return the inference profile for a specific model, or None."""
    return _load_all_raw().get(model)

# --- function 5: save_profile (function) lines 43-49 mode=ast ---
def save_profile(model: str, params: dict) -> dict:
    """Save inference profile for a model. Filters to ALLOWED_KEYS."""
    filtered = {k: v for k, v in params.items() if k in ALLOWED_KEYS}
    data = _load_all_raw()
    data[model] = filtered
    _save_all_raw(data)
    return filtered

# --- function 6: delete_profile (function) lines 52-59 mode=ast ---
def delete_profile(model: str) -> bool:
    """Remove a model's profile. Returns True if it existed."""
    data = _load_all_raw()
    if model not in data:
        return False
    del data[model]
    _save_all_raw(data)
    return True


