def _try_fill_path_params(self, path: str) -> str:
    """Fill known path parameters with safe test values."""
    replacements = {
        "{plugin_id}": "lakespeak",
        "{name}": "file_reader",
        "{book_id}": "1342",
        "{receipt_id}": "_smoke_nonexistent_",
        "{fingerprint}": "_smoke_nonexistent_",
        "{session_id}": "_smoke_nonexistent_",
        "{pack_id}": "_smoke_nonexistent_",
        "{anchor}": "water",
        "{model}": "qwen2.5:7b-instruct",
        "{filename}": "_smoke_nonexistent_",
        "{help_id}": "gpt-prompt",
        "{provider}": "openai",
        "{index}": "0",
        "{tag}": "gpt-prompt",
        "{node_id}": "_smoke_nonexistent_",
        "{project_id}": "_smoke_nonexistent_",
        "{app_id}": "_smoke_nonexistent_",
        "{feature_id}": "_smoke_nonexistent_",
        "{tweak_id}": "_smoke_nonexistent_",
        "{symbol_id}": "_smoke_nonexistent_",
        "{word}": "water",
    }
    for param, value in replacements.items():
        path = path.replace(param, value)
    return path

# --- function 10: Masher._enqueue (method) lines 565-589 mode=ast ---
def _enqueue(
    self,
    method: str,
    url: str,
    target: str,
    intent: str,
    expected: dict,
    payload: Optional[dict] = None,
):
    self._seq += 1
    action = Action(
        run_id=self.run_id,
        seq=self._seq,
        ts_utc=ts_utc(),
        mono_ns=mono_ns(),
        boot_id=BOOT_ID,
        action=method,
        target=target,
        url=url,
        payload=payload,
        payload_hash=_hash_payload(payload),
        intent=intent,
        expected=expected,
    )
    self._queue.append(action)

# --- function 11: Masher._enqueue_skip (method) lines 591-605 mode=ast ---
def _enqueue_skip(self, method: str, url: str, target: str, reason: str):
    self._seq += 1
    action = Action(
        run_id=self.run_id,
        seq=self._seq,
        ts_utc=ts_utc(),
        mono_ns=mono_ns(),
        boot_id=BOOT_ID,
        action=method,
        target=target,
        url=url,
        intent="SKIP",
        skip_reason=reason,
    )
    self._queue.append(action)

# --- function 12: Masher.write_action (method) lines 609-612 mode=ast ---
def write_action(self, action: Action) -> None:
    line = json.dumps(asdict(action), separators=(",", ":"), sort_keys=True)
    with open(self.actions_path, "a", encoding="utf-8") as f:
        f.write(line + "\n")


