async def stats_snapshot(self) -> Dict[str, Any]:
    stats = self.bridge.stats()
    if self.bridge.loaded:
        return stats
    disk_stats = await asyncio.to_thread(self._compute_disk_stats)
    stats.update(disk_stats)
    return stats

