    m = next((p for p in _plugins if p.id == plugin_id), None)
    if not m:
        return JSONResponse({"error": "not found"}, 404)
    # Find which scan dir contains this plugin
    pcheck_dir = _repo_root / "plugins"
    for sd in _scan_dirs:
        if (sd / m.id).is_dir():
            pcheck_dir = sd
