# --- function 5: ReasoningService.extract_subject (method) lines 38-54 mode=ast ---
@staticmethod
def extract_subject(question: str) -> str:
    q = question.lower()
    for pattern, keyword in [
        ("what does", "does"),
        ("what do", "do"),
        ("what is", "is"),
        ("what are", "are"),
    ]:
        if pattern in q:
            parts = q.split()
            if keyword in parts:
                idx = parts.index(keyword)
                if idx + 1 < len(parts):
                    return parts[idx + 1]
    words = question.lower().replace("?", "").split()
    return words[-1] if words else question

# --- function 6: ReasoningService._ensure_engine_sync (method) lines 56-67 mode=ast ---
def _ensure_engine_sync(self):
    if self._engine is not None:
        return self._engine
    with self._lock:
        if self._engine is None:
            from reasoning_engine.engine import ReasoningEngine

            engine = ReasoningEngine()
            engine.scan_and_update_indexes()
            self._engine = engine
            LOGGER.info("Reasoning engine loaded in-process")
    return self._engine

# --- function 7: ReasoningService.ensure_engine (async_method) lines 69-70 mode=ast ---
async def ensure_engine(self):
    return await asyncio.to_thread(self._ensure_engine_sync)

# --- function 8: ReasoningService.query_what_does_x_do (async_method) lines 72-75 mode=ast ---
async def query_what_does_x_do(self, question: str, topk: int = 8):
    subject = self.extract_subject(question)
    engine = await self.ensure_engine()
    return await asyncio.to_thread(engine.query_what_does_x_do, subject, topk)


