def queue(self, limit: int = 50, offset: int = 0) -> dict[str, Any]:
    limit = min(limit, 200)
    try:
        correction_queue = self.state.get_correction_queue()
    except ImportError:
        raise self._plugin_unavailable()
    entries = correction_queue.pending(limit=limit, offset=offset)
    return {"entries": entries, "count": len(entries)}

# --- function 5: SpellcheckQueueService.resolve (method) lines 52-91 mode=ast ---
def resolve(self, *, entry_id: str, action: str, final_token: str) -> dict[str, Any]:
    if not entry_id or action not in ("accept", "reject", "edit"):
        raise HTTPException(400, "id and action (accept/reject/edit) required")

    try:
        correction_queue = self.state.get_correction_queue()
    except ImportError:
        raise self._plugin_unavailable()
    # Scan pending entries in pages so older items aren't missed.
    entry = None
    page_size = 500
    offset = 0
    while True:
        pending = correction_queue.pending(limit=page_size, offset=offset)
        if not pending:
            break
        entry = next((item for item in pending if item.get("id") == entry_id), None)
        if entry is not None:
            break
        if len(pending) < page_size:
            break
        offset += page_size
    if not entry:
        raise HTTPException(404, f"No pending entry with id={entry_id}")

    ok = correction_queue.resolve(entry_id, action, final_token)
    if not ok:
        raise HTTPException(500, "Failed to resolve entry")

    if action in ("accept", "edit"):
        try:
            alias_map = self.state.get_alias_map()
        except ImportError:
            raise self._plugin_unavailable()
        original = entry.get("original", "")
        canonical = final_token or entry.get("suggestion", "")
        if original and canonical:
            alias_map.add(original, canonical)

    return {"ok": True, "action": action, "entry_id": entry_id}

# --- function 6: SpellcheckQueueService.stats (method) lines 93-101 mode=ast ---
def stats(self) -> dict[str, Any]:
    try:
        correction_queue = self.state.get_correction_queue()
        alias_map = self.state.get_alias_map()
    except ImportError:
        raise self._plugin_unavailable()
    stats = correction_queue.stats()
    stats["alias_count"] = alias_map.count
    return stats


