def resolve(self, symbol_ids: list[Any]) -> dict[str, Any]:
    if not symbol_ids or not isinstance(symbol_ids, list):
        raise HTTPException(400, "symbol_ids must be a non-empty list")
    try:
        wolf = self.plugin_gateway.get_wolf_engine()
        gnome = wolf.gnome
        resolved = {}
        for sid in symbol_ids:
            sid_int = int(sid)
            token = gnome.get_token(sid_int)
            resolved[str(sid)] = token or f"<unknown:{sid}>"
        return {"resolved": resolved}
    except ImportError:
        raise HTTPException(503, "Wolf Engine not available")
    except Exception as exc:
        raise HTTPException(500, _safe_error(exc))

# --- function 3: SymbolGraphService.search (method) lines 35-103 mode=ast ---
def search(self, q: str = "", limit: int = 20) -> dict[str, Any]:
    limit = min(limit, 200)
    try:
        wolf = self.plugin_gateway.get_wolf_engine()
        generate_symbol_id = self.plugin_gateway.import_attr(
            "wolf_engine",
            "wolf_engine.gnome.symbolizer",
            "generate_symbol_id",
        )
        gnome = wolf.gnome
        query = (q or "").lower().strip()

        if not query:
            top = wolf.get_top_symbols(limit=limit)
            results = []
            for entry in top:
                sid = entry.get("symbol_id", 0)
                token = gnome.get_token(sid) or f"<{sid}>"
                results.append(
                    {
                        "token": token,
                        "symbol_id": str(sid),
                        "resonance": entry.get("resonance", 0),
                        "co_occurrence_count": entry.get("co_occurrence_count", 0),
                    }
                )
            return {"results": results, "query": query}

        results = []
        sym_data = gnome.get_symbol(query)
        if sym_data:
            sid = sym_data.symbol_id_64
            forge_data = wolf.query_symbol(sid)
            results.append(
                {
                    "token": query,
                    "symbol_id": str(sid),
                    "resonance": forge_data.get("resonance", 0) if forge_data else 0,
                    "co_occurrence_count": len(forge_data.get("co_occurrence", {})) if forge_data else 0,
                    "neighbors": list(forge_data.get("co_occurrence", {}).keys())[:10] if forge_data else [],
                }
            )
        else:
            sid = generate_symbol_id(query)
            forge_data = wolf.query_symbol(sid)
            if forge_data:
                results.append(
                    {
                        "token": query,
                        "symbol_id": str(sid),
                        "resonance": forge_data.get("resonance", 0),
                        "co_occurrence_count": len(forge_data.get("co_occurrence", {})),
                        "neighbors": list(forge_data.get("co_occurrence", {}).keys())[:10],
                    }
                )

        for result in results:
            if "neighbors" in result:
                resolved_neighbors = []
                for neighbor_id in result["neighbors"]:
                    token = gnome.get_token(int(neighbor_id)) if isinstance(neighbor_id, (int, str)) else None
                    resolved_neighbors.append(token or f"<{neighbor_id}>")
                result["neighbors"] = resolved_neighbors

        return {"results": results, "query": query}
    except ImportError:
        raise HTTPException(503, "Wolf Engine not available")
    except Exception as exc:
        raise HTTPException(500, _safe_error(exc))

# --- function 4: SymbolGraphService.top (method) lines 105-127 mode=ast ---
def top(self, limit: int = 20) -> dict[str, Any]:
    limit = min(limit, 200)
    try:
        wolf = self.plugin_gateway.get_wolf_engine()
        gnome = wolf.gnome
        top = wolf.get_top_symbols(limit=limit)
        results = []
        for entry in top:
            sid = entry.get("symbol_id", 0)
            token = gnome.get_token(sid) or f"<{sid}>"
            results.append(
                {
                    "token": token,
                    "symbol_id": str(sid),
                    "resonance": entry.get("resonance", 0),
                    "co_occurrence_count": entry.get("co_occurrence_count", 0),
                }
            )
        return {"results": results}
    except ImportError:
        raise HTTPException(503, "Wolf Engine not available")
    except Exception as exc:
        raise HTTPException(500, _safe_error(exc))


