def _sanitize_plugin_ids(
    self,
    values: Any,
    *,
    max_items: int,
) -> List[str] | None:
    plugin_ids = self._sanitize_text_list(
        values,
        max_items=max_items,
        max_len=128,
    )
    for plugin_id in plugin_ids:
        if not self._PLUGIN_ID_RE.fullmatch(plugin_id):
            return None
    return plugin_ids

