def set_properties(self, hostname: str = "", version: str = "",
                   caps: Optional[dict] = None) -> None:
    """Set TXT record properties before start()."""
    self._props = {
        "machine_id": self._machine_id,
        "hostname": hostname,
        "version": version,
        "caps": json.dumps(caps or {}, separators=(",", ":")),
    }

