def start_discovery(self, port: int = 5060) -> bool:
    """Start mDNS broadcast + browsing. Auto-registers discovered peers.

    Returns True if discovery started, False if zeroconf unavailable.
    """
    try:
        from clearbox_node.core.discovery import MeshDiscovery
    except ImportError:
        logger.warning("zeroconf not installed — mDNS discovery disabled")
        return False

    caps = self.get_local_caps()
    self._discovery = MeshDiscovery(machine_id=self.local_node_id, port=port)
    self._discovery.set_properties(
        hostname=caps.get("hostname", ""),
        version="0.6.0",
        caps={"cpu": caps.get("cpu_cores", 0),
              "ram": caps.get("ram_gb", 0),
              "gpu": caps.get("gpu_name") or "none"},
    )
    self._discovery.set_on_change(self._on_peer_change)
    try:
        self._discovery.start()
        logger.info("mDNS discovery started")
        return True
    except Exception as e:
        logger.warning("mDNS discovery failed to start: %s", e)
        self._discovery = None
        return False

# --- function 20: NodeEngine.stop_discovery (method) lines 337-342 mode=ast ---
def stop_discovery(self) -> None:
    """Stop mDNS broadcast + browsing."""
    if self._discovery:
        self._discovery.stop()
        self._discovery = None
        logger.info("mDNS discovery stopped")

# --- function 21: NodeEngine._on_peer_change (method) lines 344-375 mode=ast ---
def _on_peer_change(self) -> None:
    """Callback from MeshDiscovery when peers appear/disappear.

    Auto-registers new mDNS peers into the node registry so they show
    up in the UI without manual IP:port entry.
    """
    if not self._discovery:
        return
    for peer in self._discovery.peers():
        mid = peer.get("machine_id", "")
        if not mid or mid == self.local_node_id:
            continue
        if mid not in self._nodes:
            # Parse caps from the mDNS TXT record
            caps_raw = peer.get("caps", "{}")
            try:
                caps = json.loads(caps_raw) if isinstance(caps_raw, str) else caps_raw
            except (json.JSONDecodeError, TypeError):
                caps = {}
            node = NodeInfo(
                node_id=mid,
                hostname=peer.get("hostname", ""),
                ip=peer.get("ip", ""),
                port=peer.get("port", 5060),
                caps_summary=caps,
                pairing_state="unpaired",
                last_seen=peer.get("last_seen", time.time()),
            )
            self._nodes[mid] = node
            logger.info("Auto-registered mDNS peer: %s (%s) @ %s:%d",
                        mid, node.hostname, node.ip, node.port)
            self._persist()

