def pending(self, limit: int = 50, offset: int = 0) -> list[dict]:
    """Return pending entries, newest first."""
    entries = [r for r in self._read_all() if r.get("status") == "pending"]
    entries.sort(key=lambda r: r.get("timestamp", 0), reverse=True)
    return entries[offset:offset + limit]

# --- function 26: CorrectionQueue.stats (method) lines 468-476 mode=ast ---
def stats(self) -> dict:
    """Return counts by status."""
    all_entries = self._read_all()
    result: dict[str, int] = {"pending": 0, "accepted": 0, "rejected": 0, "edited": 0, "total": 0}
    for rec in all_entries:
        status = rec.get("status", "pending")
        result[status] = result.get(status, 0) + 1
        result["total"] += 1
    return result

# --- function 27: CorrectionQueue._read_all (method) lines 480-492 mode=ast ---
def _read_all(self) -> list[dict]:
    if not self._path.exists():
        return []
    lines: list[dict] = []
    with open(self._path, "r", encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if line:
                try:
                    lines.append(json.loads(line))
                except json.JSONDecodeError:
                    pass
    return lines

# --- function 28: CorrectionQueue._write_all (method) lines 494-498 mode=ast ---
def _write_all(self, records: list[dict]) -> None:
    self.data_dir.mkdir(parents=True, exist_ok=True)
    with open(self._path, "w", encoding="utf-8") as fh:
        for rec in records:
            fh.write(json.dumps(rec, ensure_ascii=False) + "\n")


