# --- function 14: _detect_gpu_type (function) lines 302-340 mode=ast ---
def _detect_gpu_type() -> str:
    """Auto-detect GPU backend.  Returns 'rocm', 'cuda', or 'cpu'."""
    # --- NVIDIA: probe nvidia-smi ---
    try:
        r = subprocess.run(
            ["nvidia-smi", "--query-gpu=name", "--format=csv,noheader"],
            capture_output=True, text=True, timeout=10,
        )
        if r.returncode == 0 and r.stdout.strip():
            return "cuda"
    except (FileNotFoundError, subprocess.TimeoutExpired):
        pass

    # --- AMD on Windows: probe WMI ---
    if os.name == "nt":
        try:
            r = subprocess.run(
                ["wmic", "path", "win32_VideoController", "get", "Name"],
                capture_output=True, text=True, timeout=10,
            )
            if r.returncode == 0:
                names = r.stdout.lower()
                if "amd" in names or "radeon" in names:
                    return "rocm"
        except (FileNotFoundError, subprocess.TimeoutExpired):
            pass
    else:
        # --- AMD on Linux/WSL: probe rocm-smi ---
        try:
            r = subprocess.run(
                ["rocm-smi", "--showproductname"],
                capture_output=True, text=True, timeout=10,
            )
            if r.returncode == 0 and r.stdout.strip():
                return "rocm"
        except (FileNotFoundError, subprocess.TimeoutExpired):
            pass

    return "cpu"

