def _detect_msvc_or_cmake() -> bool:
    """Check for cl.exe (MSVC) or cmake on PATH — needed for source builds."""
    for args in [["cmake", "--version"], ["where", "cl"]]:
        try:
            r = subprocess.run(args, capture_output=True, text=True, timeout=10)
            if r.returncode == 0:
                return True
        except (FileNotFoundError, subprocess.TimeoutExpired):
            continue
    return False

# --- function 18: _detect_ollama (function) lines 370-385 mode=ast ---
def _detect_ollama() -> bool:
    """Ollama: try CLI, then HTTP probe on 11434."""
    try:
        r = subprocess.run(["ollama", "--version"],
                           capture_output=True, text=True, timeout=10)
        if r.returncode == 0:
            return True
    except (FileNotFoundError, subprocess.TimeoutExpired):
        pass
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(2)
            s.connect(("127.0.0.1", 11434))
        return True
    except OSError:
        return False

