def _data_root() -> Path:
    """Installer/runtime data root (must match security/data_paths.py)."""
    global _DATA_ROOT_OVERRIDE
    if _DATA_ROOT_OVERRIDE is not None:
        return _DATA_ROOT_OVERRIDE
