# --- function 5: ChatModeExecutor.execute (async_method) lines 53-137 mode=ast ---
async def execute(
    self,
    *,
    req: ChatSendRequest,
    msg: str,
    request: Request,
    route: Any,
    rctx: Any,
    original_mode: str,
    model_name: str,
) -> ChatSendResponse:
    trace_id = self._trace_id(request)
    branch = (req.side_chat_id or "").strip() or "main"

    if req.mode == "llm":
        return await self.llm_service.execute(
            req=req,
            msg=msg,
            model_name=model_name,
            route=route,
            rctx=rctx,
            original_mode=original_mode,
            trace_id=trace_id,
            branch=branch,
            build_seat=self._build_seat,
        )

    if req.mode == "grounded":
        return await self.grounded_service.execute(
            req=req,
            msg=msg,
            model_name=model_name,
            route=route,
            rctx=rctx,
            branch=branch,
            build_seat=self._build_seat,
        )

    if req.mode == "reasoning":
        resp = await self.reasoning_service.execute(
            req=req,
            msg=msg,
            route=route,
            rctx=rctx,
            branch=branch,
            build_seat=self._build_seat,
            ensure_lexicon_loaded=self._ensure_lexicon_loaded,
        )
        if resp is not None:
            return resp

    if req.mode == "multi_llm":
        if not self.multi_llm_service:
            return ChatSendResponse(
                mode=req.mode,
                source="bridge_router",
                response="",
                reasoning_trace={"routing": route.telemetry_block(rctx)},
                error={
                    "type": "misconfigured",
                    "message": "multi_llm service is not configured.",
                },
            )
        return await self.multi_llm_service.execute(
            req=req,
            msg=msg,
            request=request,
            route=route,
            rctx=rctx,
        )

    LOGGER.warning("Unknown chat mode: %s", req.mode)
    return ChatSendResponse(
        mode=req.mode,
        source="bridge_router",
        response="",
        reasoning_trace={"routing": route.telemetry_block(rctx)},
        error={
            "type": "unknown_mode",
            "message": (
                f"Unknown mode: {req.mode}. "
                "Allowed base modes: llm, grounded, reasoning, multi_llm."
            ),
        },
    )


