def stop(self) -> None:
    """Unregister and close."""
    if self._zc and self._info:
        try:
            self._zc.unregister_service(self._info)
        except Exception:
            pass
    if self._zc:
        try:
            self._zc.close()
        except Exception:
            pass
    self._zc = None
    self._info = None
    self._browser = None
    logger.info("mDNS stopped")

