def _node_base(self, node_id: str) -> str:
    """Get base URL for a registered node. Raises ValueError if not found."""
    node = self.get_node(node_id)
    if not node:
        raise ValueError(f"Node not found: {node_id}")
    return f"http://{node.ip}:{node.port}"

