def list_ids(self) -> List[Dict[str, str]]:
    """Return compact summaries for all help IDs."""
    return [
        {
            "help_id": hid,
            "label": entry.get("label", ""),
            "category": entry.get("category", ""),
            "snippet": (entry.get("layer1", {}) or {}).get("what", "")[:140],
            "tutorial_available": entry.get("tutorial_available", False),
            "difficulty": entry.get("difficulty", ""),
            "icon": entry.get("icon", ""),
        }
        for hid, entry in sorted(self._content.items())
    ]

# --- function 7: HelpSystemEngine.get_stats (method) lines 105-121 mode=ast ---
def get_stats(self) -> Dict[str, Any]:
    """Return stats about the loaded content."""
    categories: Dict[str, int] = {}
    layers = {"layer1": 0, "layer2": 0, "layer3": 0}

    for entry in self._content.values():
        cat = entry.get("category", "Uncategorized")
        categories[cat] = categories.get(cat, 0) + 1
        for layer_key in ("layer1", "layer2", "layer3"):
            if entry.get(layer_key):
                layers[layer_key] += 1

    return {
        "total_ids": len(self._content),
        "categories": categories,
        "layers_coverage": layers,
    }


