def add(self, misspelling: str, canonical: str) -> None:
    """Register an accepted correction."""
    self._ensure_loaded()
    key = misspelling.lower().strip()
    val = canonical.lower().strip()
    if key and val and key != val:
        self._map[key] = val
        self._save()
        LOGGER.info("AliasMap: %r → %r", key, val)

