def remove(self, misspelling: str) -> bool:
    """Revoke a previously accepted correction.  Returns True if found."""
    self._ensure_loaded()
    key = misspelling.lower().strip()
    if key in self._map:
        del self._map[key]
        self._save()
        return True
    return False

