# --- function 2: SystemPulseEngine.snapshot (method) lines 27-87 mode=ast ---
def snapshot(self) -> Dict[str, Any]:
    """Full system snapshot — CPU, RAM, disk, GPU."""
    import psutil
    now = time.time()

    cpu_pct = psutil.cpu_percent(interval=0.2)
    cpu_freq = psutil.cpu_freq()
    cpu_count = psutil.cpu_count(logical=True)
    cpu_physical = psutil.cpu_count(logical=False)

    mem = psutil.virtual_memory()
    swap = psutil.swap_memory()

    disks = []
    for part in psutil.disk_partitions(all=False):
        try:
            usage = psutil.disk_usage(part.mountpoint)
            disks.append({
                "mountpoint": part.mountpoint,
                "device": part.device,
                "fstype": part.fstype,
                "total_gb": round(usage.total / 1e9, 1),
                "used_gb":  round(usage.used  / 1e9, 1),
                "free_gb":  round(usage.free  / 1e9, 1),
                "pct":      usage.percent,
            })
        except Exception:
            pass

    gpu = self._gpu_stats()

    snap = {
        "ts": now,
        "cpu": {
            "pct": cpu_pct,
            "cores_logical": cpu_count,
            "cores_physical": cpu_physical,
            "freq_mhz": round(cpu_freq.current, 0) if cpu_freq else None,
            "freq_max_mhz": round(cpu_freq.max, 0) if cpu_freq else None,
        },
        "ram": {
            "total_gb":     round(mem.total    / 1e9, 2),
            "used_gb":      round(mem.used     / 1e9, 2),
            "available_gb": round(mem.available/ 1e9, 2),
            "pct":          mem.percent,
        },
        "swap": {
            "total_gb": round(swap.total / 1e9, 2),
            "used_gb":  round(swap.used  / 1e9, 2),
            "pct":      swap.percent,
        },
        "disks": disks,
        "gpu": gpu,
    }

    with self._lock:
        self._history.append({"ts": now, "cpu_pct": cpu_pct, "ram_pct": mem.percent})
        if len(self._history) > self._max_history:
            self._history = self._history[-self._max_history:]

    return snap

