def create_listing(self, payload: Dict[str, Any]) -> Dict[str, Any]:
    with self._lock:
        self.ensure_initialized()
        if not self._feature_enabled("listings"):
            return self._feature_disabled("listings")

        plugin_id = self._sanitize_text(
            payload.get("plugin_id", ""),
            max_len=128,
        )
        if not plugin_id or not self._PLUGIN_ID_RE.fullmatch(plugin_id):
            return self._validation_error(
                "plugin_id is required and may only contain letters, digits, _, ., -",
                field="plugin_id",
            )

        name = self._sanitize_text(payload.get("name", ""), max_len=120)
        if not name:
            return self._validation_error(
                "name is required",
                field="name",
            )

        description = self._sanitize_text(
            payload.get("description", ""),
            max_len=2000,
        )
        plugin_version = self._sanitize_text(
            payload.get("plugin_version", ""),
            max_len=64,
        )
        manifest_url = self._sanitize_text(
            payload.get("manifest_url", ""),
            max_len=2048,
        )
        if manifest_url and not self._is_valid_manifest_url(manifest_url):
            return self._validation_error(
                "manifest_url must be an http(s) URL with a host",
                field="manifest_url",
            )

        category = self._sanitize_text(
            payload.get("category", ""),
            max_len=64,
        )

        try:
            price = int(payload.get("price", 0) or 0)
        except (TypeError, ValueError):
            return self._validation_error(
                "price must be an integer",
                field="price",
            )
        if price < 0 or price > 1_000_000:
            return self._validation_error(
                "price out of allowed range",
                field="price",
            )

        clean = {
            "plugin_id": plugin_id,
            "name": name,
            "description": description,
            "plugin_version": plugin_version,
            "manifest_url": manifest_url,
            "category": category,
            "price": price,
            "downloads": 0,
        }
        envelope = self._sign_object("plugin_listing", clean)
        self._append_jsonl(self._listings_path, envelope)
        self._upsert_listing(envelope)
        return {"ok": True, "message": "listing created", "listing": envelope}

# --- function 11: ClearboxAISocialEngine.search_listings (method) lines 274-319 mode=ast ---
def search_listings(
    self,
    category: str = "",
    author_node_id: str = "",
    sort_by: str = "downloads",
) -> Dict[str, Any]:
    self.ensure_initialized()
    if not self._feature_enabled("listings"):
        return self._feature_disabled("listings")

    category = self._sanitize_text(category, max_len=64)
    author_node_id = self._sanitize_text(author_node_id, max_len=256)
    if sort_by not in {"downloads", "name", "first_seen"}:
        return self._validation_error(
            "invalid sort_by value",
            field="sort_by",
        )

    order_by = {
        "downloads": "downloads DESC",
        "name": "name ASC",
        "first_seen": "first_seen DESC",
    }[sort_by]

    query = "SELECT * FROM plugins WHERE 1=1"
    params: List[Any] = []

    if category:
        query += " AND category = ?"
        params.append(category)

    if author_node_id:
        query += " AND author_node_id = ?"
        params.append(author_node_id)

    query += f" ORDER BY {order_by}"

    conn = sqlite3.connect(self._db_path)
    conn.row_factory = sqlite3.Row
    try:
        rows = conn.execute(query, params).fetchall()
        listings = [dict(row) for row in rows]
    finally:
        conn.close()

    return {"ok": True, "message": "search complete", "listings": listings}

