def sync_peer(
    self,
    node_id: str,
    host: str,
    port: int,
    scheme: str = "http",
) -> Dict[str, Any]:
    self.ensure_initialized()
    if not self._feature_enabled("manual_sync"):
        return self._feature_disabled("manual_sync")

    node_id = self._sanitize_text(node_id, max_len=256)
    host = self._sanitize_text(host, max_len=253).lower()
    if not host or not self._HOST_RE.fullmatch(host):
        return self._validation_error(
            "invalid host",
            field="host",
        )
    if not isinstance(port, int) or port < 1 or port > 65535:
        return self._validation_error(
            "invalid port",
            field="port",
        )
    if scheme not in {"http", "https"}:
        return self._validation_error(
            "invalid scheme",
            field="scheme",
        )

    # Deliberately a stub for the first Codex pass.
    # This is where paired-node fetch, verify, and import will go.
    return {
        "ok": False,
        "message": "manual peer sync not implemented yet",
        "peer_node_id": node_id,
        "imported_profile": False,
        "imported_listings": 0,
        "error": {
            "code": "not_implemented",
            "host": host,
            "port": port,
            "scheme": scheme,
        },
    }

