def _sanitize_text_list(
    self,
    values: Any,
    *,
    max_items: int,
    max_len: int,
) -> List[str]:
    if not isinstance(values, list):
        return []
    out: List[str] = []
    for item in values[:max_items]:
        text = self._sanitize_text(item, max_len=max_len)
        if text:
            out.append(text)
    return out

