def __init__(self, profile: dict):
    self.profile = profile
    self.name = profile.get("name", "unknown")

# --- function 2: RouteEngine.prepare (method) lines 47-58 mode=ast ---
def prepare(self, mode: str, prompt: str) -> RouteContext:
    """Build a RouteContext from the loaded profile for this request."""
    ctx = RouteContext(mode=mode, user_prompt=prompt)
    for stage in self.profile.get("pipeline", []):
        sid = stage.get("id", stage["type"])
        cfg = stage.get("config", {})
        if stage.get("enabled"):
            ctx.configs_by_type[stage["type"]] = cfg
            ctx.configs_by_id[sid] = cfg
        else:
            ctx.disabled_stages.add(stage["type"])
    return ctx

# --- function 3: RouteEngine.enabled (method) lines 60-62 mode=ast ---
def enabled(self, ctx: RouteContext, stage_type: str) -> bool:
    """Is the given stage type enabled in this profile?"""
    return stage_type not in ctx.disabled_stages

# --- function 4: RouteEngine.config (method) lines 64-66 mode=ast ---
def config(self, ctx: RouteContext, stage_type: str, key: str, default=None):
    """Get a config value for a stage type. Returns default if missing."""
    return ctx.configs_by_type.get(stage_type, {}).get(key, default)

# --- function 5: RouteEngine.record (method) lines 68-84 mode=ast ---
def record(self, ctx: RouteContext, stage_id: str, stage_type: str,
           enabled: bool, ms: int = 0, **extra):
    """Record a stage execution for telemetry.

    Always pass stage_type explicitly — don't derive from stage_id.
    In v1 id==type, but this will diverge in future.
    Extra kwargs are merged into the telemetry entry (e.g. redirect details).
    """
    entry = {
        "id": stage_id,
        "type": stage_type,
        "enabled": enabled,
        "ms": ms,
    }
    if extra:
        entry.update(extra)
    ctx.telemetry.append(entry)

# --- function 6: RouteEngine.parked_mode (method) lines 86-94 mode=ast ---
def parked_mode(self, ctx: RouteContext, mode: str) -> bool:
    """Is the given mode parked (should be redirected)?

    Returns True if engine_parking is enabled and mode is in park_modes.
    """
    if not self.enabled(ctx, "engine_parking"):
        return False
    park_modes = self.config(ctx, "engine_parking", "park_modes", [])
    return mode in set(park_modes or [])

# --- function 7: RouteEngine.redirect_mode (method) lines 96-100 mode=ast ---
def redirect_mode(self, ctx: RouteContext, mode: str) -> str:
    """If mode is parked, return the redirect target. Otherwise return mode as-is."""
    if self.parked_mode(ctx, mode):
        return self.config(ctx, "engine_parking", "redirect_mode", "llm")
    return mode

# --- function 8: RouteEngine.telemetry_block (method) lines 102-104 mode=ast ---
def telemetry_block(self, ctx: RouteContext) -> dict:
    """Return the complete telemetry payload for the response."""
    return {"profile": self.name, "stages": ctx.telemetry}


