def load_profile(model: str) -> dict | None:
    """Return the inference profile for a specific model, or None."""
    return _load_all_raw().get(model)

# --- function 5: save_profile (function) lines 43-49 mode=ast ---
def save_profile(model: str, params: dict) -> dict:
    """Save inference profile for a model. Filters to ALLOWED_KEYS."""
    filtered = {k: v for k, v in params.items() if k in ALLOWED_KEYS}
    data = _load_all_raw()
    data[model] = filtered
    _save_all_raw(data)
    return filtered

# --- function 6: delete_profile (function) lines 52-59 mode=ast ---
def delete_profile(model: str) -> bool:
    """Remove a model's profile. Returns True if it existed."""
    data = _load_all_raw()
    if model not in data:
        return False
    del data[model]
    _save_all_raw(data)
    return True


