def _enqueue(
    self,
    method: str,
    url: str,
    target: str,
    intent: str,
    expected: dict,
    payload: Optional[dict] = None,
):
    self._seq += 1
    action = Action(
        run_id=self.run_id,
        seq=self._seq,
        ts_utc=ts_utc(),
        mono_ns=mono_ns(),
        boot_id=BOOT_ID,
        action=method,
        target=target,
        url=url,
        payload=payload,
        payload_hash=_hash_payload(payload),
        intent=intent,
        expected=expected,
    )
    self._queue.append(action)

