def _enqueue_skip(self, method: str, url: str, target: str, reason: str):
    self._seq += 1
    action = Action(
        run_id=self.run_id,
        seq=self._seq,
        ts_utc=ts_utc(),
        mono_ns=mono_ns(),
        boot_id=BOOT_ID,
        action=method,
        target=target,
        url=url,
        intent="SKIP",
        skip_reason=reason,
    )
    self._queue.append(action)

