def _get_axis_name(self, axis_id: int) -> str:
    """Map axis ID to semantic name (Xbox controller layout)."""
    axis_names = {
        0: "left_stick_x",
        1: "left_stick_y",
        2: "left_trigger",
        3: "right_stick_x",
        4: "right_stick_y",
        5: "right_trigger"
    }
    return axis_names.get(axis_id, f"axis_{axis_id}")

