@classmethod
def from_any(cls, value: Union["ChronosMode", str]) -> "ChronosMode":
    if isinstance(value, ChronosMode):
        return value
    v = str(value).strip().lower()
    if v in ("live", "l"):
        return cls.LIVE
    if v in ("replay", "r"):
        return cls.REPLAY
    if v in ("simulated", "sim", "s"):
        return cls.SIMULATED
    raise ValueError(f"Unknown ChronosMode: {value!r}")

