def __init__(self, config: dict):
    self.config = config
    self.source = config.get("capture", {}).get("source", "auto")
    self.region_type = config.get("capture", {}).get("region", "full")

    self.sct = mss.mss()
    self.monitor = self._get_monitor()

    print(f"[+] FrameCapture initialized")
