def __init__(self, config: SensorConfig, chronos: ChronosManager, event_mgr):
    super().__init__(config, chronos, event_mgr)
    self.pygame = None
    self.joystick = None
    self.controllers: List = []
    self.prev_button_states: Dict = {}
    self.prev_axis_values: Dict = {}

