# --- function 1: get_idle_duration (function) lines 58-64 mode=ast ---
def get_idle_duration():
    """Get seconds since last user input (keyboard/mouse)"""
    lastInputInfo = LASTINPUTINFO()
    lastInputInfo.cbSize = ctypes.sizeof(lastInputInfo)
    ctypes.windll.user32.GetLastInputInfo(ctypes.byref(lastInputInfo))
    millis = ctypes.windll.kernel32.GetTickCount() - lastInputInfo.dwTime
    return millis / 1000.0

# --- function 2: get_active_window (function) lines 66-82 mode=ast ---
def get_active_window():
    """Get currently active window title and process PID"""
    try:
        import win32gui
        import win32process

        hwnd = win32gui.GetForegroundWindow()
        if hwnd == 0:
            return None, None, None

        _, pid = win32process.GetWindowThreadProcessId(hwnd)
        window_title = win32gui.GetWindowText(hwnd)

        return hwnd, pid, window_title
    except Exception as e:
        logging.debug(f"Error getting active window: {e}")
        return None, None, None

# --- function 3: get_process_info (function) lines 84-92 mode=ast ---
def get_process_info(pid):
    """Get process name and path from PID"""
    try:
        p = psutil.Process(pid)
        name = p.name()
        path = p.exe() if p.exe() else ""
        return name, path
    except (psutil.NoSuchProcess, psutil.AccessDenied):
        return None, None

