def close(self) -> None:
    """
    Flush any remaining records and mark writer as closed.

    No further windows may be submitted after this.
    """
    with self._lock:
        if not self._closed:
            self._flush_locked()
            self._closed = True
            # Save string dictionary
            self.string_dict.save()

