def test_replay_speed():
    """Test REPLAY mode speed multiplier."""
    c = ChronosManager()
    c.initialize(ChronosMode.REPLAY, {
        "replay_start_time": 1000.0,
        "replay_speed": 2.0,
        "replay_offset": 0.0,
    })
    t1 = c.now()
