def _now_replay_locked(self) -> float:
    wall_now = time.time()
    elapsed_wall = wall_now - self.replay_anchor_wall
    logical = (
        self.replay_start_time
        + elapsed_wall * self.replay_speed
        + self.replay_offset
    )
    return logical

