def _shutdown(self) -> None:
    """Clean shutdown of all systems."""
    print("  Flushing PulseWriter...")
    try:
        self.pulse_writer.flush(reason="shutdown")
    except Exception as e:
        print(f"    ❌ Flush error: {e}")

    print("  Closing Forge Memory...")
    try:
        self.pulse_writer.close()
        self.binary_log.close()  # Close memory-mapped file
    except Exception as e:
        print(f"    ❌ Close error: {e}")
        import traceback
        traceback.print_exc()

    # Stop activity logger if started
    try:
        if getattr(self, 'activity_service', None) is not None:
            self.activity_service.stop()
            print("  ✓ ActivityLogger stopped")
    except Exception as e:
        print(f"    ❌ ActivityLogger stop error: {e}")
        import traceback
        traceback.print_exc()

    # Stop input logger if started
    try:
        if getattr(self, 'input_service', None) is not None:
            self.input_service.stop()
            print("  ✓ InputLogger stopped")
    except Exception as e:
        print(f"    ❌ InputLogger stop error: {e}")
        import traceback
        traceback.print_exc()

    # Stop process logger if started
    try:
        if getattr(self, 'process_service', None) is not None:
            self.process_service.stop()
            print("  ✓ ProcessLogger stopped")
    except Exception as e:
        print(f"    ❌ ProcessLogger stop error: {e}")
        import traceback
        traceback.print_exc()

    # Stop network logger if started
    try:
        if getattr(self, 'network_service', None) is not None:
            self.network_service.stop()
            print("  ✓ NetworkLogger stopped")
    except Exception as e:
        print(f"    ❌ NetworkLogger stop error: {e}")
        import traceback
        traceback.print_exc()

    # Final statistics
    elapsed = self.chronos.now() - self.start_time

    print("\n" + "="*80)
    print("Session Complete")
    print("="*80)
    print(f"\nDuration: {elapsed:.1f} seconds")
    print(f"Windows Captured: {self.windows_captured}")
    print(f"Forge Records: {self.binary_log.get_record_count()}")

    if self.enable_events:
        print(f"\nEvents Recorded: {self.events_recorded}")
        print(f"  High EOMM: {self.high_eomm_count}")
        print(f"  Operator Triggers: {self.operator_triggers}")

        # Session chain summary
        chain = self.event_mgr.get_chain(self.session_id)
        print(f"\nSession Chain: {self.session_id}")
        print(f"  Events: {len(chain.event_ids)}")
