def setup_logging():
    """Configure logging output"""
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s [%(levelname)s] %(message)s',
        datefmt='%Y-%m-%d %H:%M:%S'
    )

# --- function 7: main (function) lines 167-174 mode=ast ---
def main():
    """Start activity monitoring"""
    setup_logging()

    try:
        collect_and_log()
    except KeyboardInterrupt:
        logging.info("Activity logger terminated")


