def parse_args(argv=None):
    parser = argparse.ArgumentParser(
        description="CompuCog Continuous Gamepad Logger"
    )
    parser.add_argument(
        "--poll-rate",
        type=int,
        default=60,
        help="Controller polling frequency in Hz (default: 60)",
    )
    return parser.parse_args(argv)


