def setup_logging():
    """Configure logging output"""
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s [%(levelname)s] %(message)s',
        datefmt='%Y-%m-%d %H:%M:%S'
    )

# --- function 10: main (function) lines 296-304 mode=ast ---
def main():
    """Start input activity monitoring"""
    setup_logging()

    try:
        collect_and_log()
    except KeyboardInterrupt:
        logging.info("Input logger stopped")
        sys.exit(0)


