# --- function 1: load_telemetry (function) lines 31-39 mode=ast ---
def load_telemetry(path: str) -> List[Dict]:
    """Load JSONL telemetry file"""
    entries = []
    with open(path, 'r', encoding='utf-8-sig') as f:
        for line in f:
            line = line.strip()
            if line:
                entries.append(json.loads(line))
    return entries

