        _HEADER_FMT,
        MAGIC_RECORD,
        RECORD_SCHEMA_VERSION,
        record_length,
        int(self.pulse_id),
        int(self.worker_id) & 0xFF,
        int(self.seq),
        float(self.timestamp),
        1 if self.success else 0,
        int(self.task_id_ref),
        int(self.engine_id_ref),
        int(self.transform_id_ref),
        int(self.failure_reason_ref),
