def manipulation_events_last(self, minutes: int) -> List[ForgeRecord]:
    return list(
        self.where(
            lambda r: r.error_metrics.get("eomm_score", 0) > 0.5
            and r.timestamp >= time.time() - minutes * 60
        )
    )

