def operator_frequency(self) -> Dict[str, int]:
    """Global histogram of operator usage across all windows."""
    hist: Dict[str, int] = {}
    for r in self.q.scan():
        ops = r.error_metrics.get("operators", {})
        for name in ops.keys():
            hist[name] = hist.get(name, 0) + 1
    return hist


