# --- function 1: CortexCube.__init__ (method) lines 5-7 mode=ast ---
def __init__(self, size=100):
    self.size = size
    self.cube = np.zeros((size, size, size), dtype=np.float32)

# --- function 2: CortexCube.func_to_coord (method) lines 9-13 mode=ast ---
def func_to_coord(self, func_id):
    z = func_id // (self.size * self.size)
    y = (func_id % (self.size * self.size)) // self.size
    x = func_id % self.size
    return x, y, z

# --- function 3: CortexCube.activate (method) lines 15-18 mode=ast ---
def activate(self, func_ids, scores):
    for fid, score in zip(func_ids, scores):
        x, y, z = self.func_to_coord(fid)
        self.cube[x, y, z] += score


