def setUp(self):
    self.df = pd.DataFrame({
        'a': range(10),
        'b': range(10),
        'c': range(10),
        'd': range(10),
        'e': range(10),
    })

# --- function 2: TestEngineAndState.test_validation_success (method) lines 22-28 mode=fallback ---
def test_validation_success(self):
    params = CascadeParameters(left_width=1, right_width=1, anchor_pos=2, target_path='test')
    field_map = {col: idx for idx, col in enumerate(self.df.columns)}
    engine = CascadeEngine(self.df, params, field_map)
    result = engine.execute()
    self.assertEqual(result.shape[1], 3)

# --- function 3: TestEngineAndState.test_validation_failure (method) lines 29-34 mode=fallback ---
def test_validation_failure(self):
    params = CascadeParameters(left_width=3, right_width=3, anchor_pos=0, target_path='test')
    field_map = {col: idx for idx, col in enumerate(self.df.columns)}
    with self.assertRaises(ValueError):
        CascadeEngine(self.df.iloc[:, :4], params, field_map)

# --- function 4: TestEngineAndState.test_state_manager (method) lines 35-43 mode=fallback ---
def test_state_manager(self):
    state = CascadeState(anchor_history=['a'], cascade_parameters={'N': 3}, data_map_version='v1')
    manager = StateManager(state)
    manager.add_anchor('b')
    locked = manager.lock()
    self.assertEqual(locked.anchor_history, ['a', 'b'])
    manager.update_parameters({'N': 4})
    self.assertEqual(manager.state.cascade_parameters['N'], 4)


