# --- function 1: CoreNetwork.__init__ (method) lines 5-7 mode=ast ---
def __init__(self):
    self.subscribers = defaultdict(list)
    self.queue = asyncio.Queue()

# --- function 2: CoreNetwork.publish (async_method) lines 9-13 mode=ast ---
async def publish(self, topic, message):
    """Publish a message to all subscribers of a topic."""
    if topic in self.subscribers:
        for callback in self.subscribers[topic]:
            await callback(message)

# --- function 3: CoreNetwork.subscribe (method) lines 15-17 mode=ast ---
def subscribe(self, topic, callback):
    """Subscribe a callback function to a topic."""
    self.subscribers[topic].append(callback)

# --- function 4: CoreNetwork.start_event_loop (async_method) lines 19-23 mode=ast ---
async def start_event_loop(self):
    """Start processing tasks asynchronously."""
    while True:
        topic, message = await self.queue.get()
        await self.publish(topic, message)

# --- function 5: CoreNetwork.dispatch (method) lines 25-27 mode=ast ---
def dispatch(self, topic, message):
    """Queue a message for dispatch."""
    self.queue.put_nowait((topic, message))

# --- function 6: processor (async_function) lines 34-35 mode=ast ---
async def processor(message):
    print(f"[Processor] Received: {message}")

# --- function 7: main (async_function) lines 37-45 mode=ast ---
async def main():
    network = CoreNetwork()
    network.subscribe("task.update", processor)

    asyncio.create_task(network.start_event_loop())

    for i in range(5):
        network.dispatch("task.update", f"Update #{i} from {random.randint(1000, 9999)}")
        await asyncio.sleep(0.5)


