def stop(self) -> bool:
    """
    Stop the global synchronization loop.

    Returns:
        True if stopped successfully, False otherwise
    """
    if self._running:
        logger.info("Global synchronization loop stopping")
        self._running = False
        return True
    else:
        logger.warning("Global synchronization loop already stopped")
        return False

