def allocate_neuron(self, neuron_id, chute):
    block = self._find_available_block(chute)
    self.blocks[block] = neuron_id
    self.neuron_map[neuron_id] = block
    print(f"[ALLOC] Neuron {neuron_id} -> {block} via {chute}")
    return block

