def _set_pointer(self, offset):
    high = ctypes.c_ulong(offset >> 32)
    low = ctypes.windll.kernel32.SetFilePointer(self.handle, offset & 0xFFFFFFFF, ctypes.byref(high), 0)
    if low == 0xFFFFFFFF and ctypes.GetLastError() != 0:
        raise OSError("Failed seeking to offset")


