def dynamic_import(self, module_name):
    filename = module_name.lower() + ".py"
    full_path = os.path.join(os.getcwd(), filename)
    if not os.path.exists(full_path):
        raise FileNotFoundError(f"{filename} not found for module: {module_name}")

    spec = importlib.util.spec_from_file_location(module_name, full_path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)

    cls = getattr(module, module_name, None)
    if cls is None:
        raise ImportError(f"No class {module_name} inside {filename}")

    return cls

