# --- function 5: SymbolicTranslator._calculate_similarity (method) lines 240-254 mode=ast ---
def _calculate_similarity(self, vector1, vector2):
    """Calculate cosine similarity between two vectors."""
    # Convert to numpy arrays
    v1 = np.array(vector1)
    v2 = np.array(vector2)

    # Calculate cosine similarity
    dot_product = np.dot(v1, v2)
    norm_v1 = np.linalg.norm(v1)
    norm_v2 = np.linalg.norm(v2)

    if norm_v1 == 0 or norm_v2 == 0:
        return 0

    return dot_product / (norm_v1 * norm_v2)

# --- function 6: SymbolicTranslator._string_similarity (method) lines 256-265 mode=ast ---
def _string_similarity(self, str1, str2):
    """Calculate simple string similarity."""
    # Simple Levenshtein distance-based similarity
    distance = self._levenshtein_distance(str1, str2)
    max_len = max(len(str1), len(str2))

    if max_len == 0:
        return 1.0

    return 1.0 - (distance / max_len)

# --- function 7: SymbolicTranslator._levenshtein_distance (method) lines 267-290 mode=ast ---
def _levenshtein_distance(self, str1, str2):
    """Calculate Levenshtein distance between two strings."""
    m, n = len(str1), len(str2)

    # Create distance matrix
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Initialize first row and column
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Fill the matrix
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0 if str1[i-1] == str2[j-1] else 1
            dp[i][j] = min(
                dp[i-1][j] + 1,      # Deletion
                dp[i][j-1] + 1,      # Insertion
                dp[i-1][j-1] + cost  # Substitution
            )

    return dp[m][n]

