# --- function 2: format_nvme (function) lines 21-49 mode=ast ---
def format_nvme():
    print("[FORMATTER] Opening NVMe device...")
    handle = win32file.CreateFile(
        NVME_PATH,
        win32con.GENERIC_WRITE | win32con.GENERIC_READ,
        win32con.FILE_SHARE_READ | win32con.FILE_SHARE_WRITE,
        None,
        win32con.OPEN_EXISTING,
        0,
        None
    )

    # Write signature
    buffer = NVME_SIGNATURE.ljust(SECTOR_SIZE, b'\x00')
    win32file.SetFilePointer(handle, 0, win32con.FILE_BEGIN)
    win32file.WriteFile(handle, buffer)
    print("[WRITE] Signature block written to sector 0.")

    # Zero next 100 sectors
    zero_buffer = b'\x00' * SECTOR_SIZE
    for sector in range(1, 101):
        win32file.SetFilePointer(handle, sector * SECTOR_SIZE, win32con.FILE_BEGIN)
        win32file.WriteFile(handle, zero_buffer)
        if sector % 10 == 0:
            print(f"  Cleared sector {sector}")

    handle.close()
    print("\n[SUCCESS] NVMe CortexOS formatting complete.")
    print("[READY] Drive is now fully CortexOS NVMe compatible.")


