def _start_monitor_thread(self) -> None:
    """Start the monitoring thread."""
    def monitor_loop():
        while True:
            try:
                # Perform self-regulation
                self.self_regulate()

                # Sync with global clock
                self.sync_clock()
            except Exception as e:
                logger.error(f"Error in monitor thread: {e}")

            # Sleep before next check
            time.sleep(10)

