def _find_available_block(self, chute):
    attempts = 0
    while attempts < 50000:
        x, y, z = self._generate_coords(chute)
        if (x,y,z) not in self.blocks:
            return (x,y,z)
        attempts += 1
    raise Exception("No available blocks in chute sector.")

# --- function 3: NVMeCubeStore._generate_coords (method) lines 32-42 mode=ast ---
def _generate_coords(self, chute):
    spread = CUBE_SIZE // 4
    cx, cy, cz = CRITICAL_CORE_ZONE
    offset = random.randint(1, spread)
    if chute == 'UP': return (cx, cy, cz + offset)
    if chute == 'DOWN': return (cx, cy, cz - offset)
    if chute == 'LEFT': return (cx - offset, cy, cz)
    if chute == 'RIGHT': return (cx + offset, cy, cz)
    if chute == 'FRONT': return (cx, cy - offset, cz)
    if chute == 'BACK': return (cx, cy + offset, cz)
    return (cx, cy, cz)

