def get_neighbor_count(pos):
    x, y, z = pos
    count = 0
    for dx in [-1, 0, 1]:
        for dy in [-1, 0, 1]:
            for dz in [-1, 0, 1]:
                if dx == dy == dz == 0:
                    continue
                nx, ny, nz = x + dx, y + dy, z + dz
                if 0 <= nx < CUBE_SIZE and 0 <= ny < CUBE_SIZE and 0 <= nz < CUBE_SIZE:
                    if occupancy[(nx, ny, nz)] is not None:
                        count += 1
    return count

