def find_next_available(self):
    # Simple linear search outward from center
    for radius in range(self.cube_size):
        for dx in range(-radius, radius+1):
            for dy in range(-radius, radius+1):
                for dz in range(-radius, radius+1):
                    x, y, z = self.center+dx, self.center+dy, self.center+dz
                    if self.valid(x,y,z) and not self.occupied((x,y,z)):
                        return (x,y,z)
    raise Exception("[ALLOC ERROR] No free space available.")

