def save_snapshot(self):
    self.snapshots += 1
    data = {
        "mapping": self.mapping,
        "migration_log": self.migration_log
    }
    filename = f"snapshot_v22_{self.snapshots}.json"
    with open(filename, "w") as f:
        json.dump(data, f)
    print(f"[SNAPSHOT] {filename} saved.")

