# --- function 1: LEB128Encoder.encode (method) lines 43-57 mode=ast ---
@staticmethod
def encode(value: int) -> bytes:
    """Encode integer using LEB128 format"""
    if value == 0:
        return b'\x00'

    result = bytearray()
    while value > 0:
        byte = value & 0x7F
        value >>= 7
        if value > 0:
            byte |= 0x80
        result.append(byte)

    return bytes(result)

# --- function 2: LEB128Encoder.decode (method) lines 59-76 mode=ast ---
@staticmethod
def decode(data: bytes, offset: int = 0) -> Tuple[int, int]:
    """Decode LEB128 integer, returns (value, bytes_consumed)"""
    result = 0
    shift = 0
    bytes_consumed = 0

    while offset + bytes_consumed < len(data):
        byte = data[offset + bytes_consumed]
        bytes_consumed += 1

        result |= (byte & 0x7F) << shift
        shift += 7

        if (byte & 0x80) == 0:
            break

    return result, bytes_consumed

