# --- function 2: LEB128Encoder.encode (method) lines 59-70 mode=ast ---
@staticmethod
def encode(value: int) -> bytes:
    """Encode integer using LEB128"""
    if value < 0:
        raise ValueError("LEB128 only supports non-negative integers")

    result = bytearray()
    while value >= 0x80:
        result.append((value & 0x7F) | 0x80)
        value >>= 7
    result.append(value & 0x7F)
    return bytes(result)

# --- function 3: LEB128Encoder.decode (method) lines 72-89 mode=ast ---
@staticmethod
def decode(data: bytes, offset: int = 0) -> Tuple[int, int]:
    """Decode LEB128 integer, returns (value, bytes_consumed)"""
    result = 0
    shift = 0
    bytes_read = 0

    while offset + bytes_read < len(data):
        byte = data[offset + bytes_read]
        bytes_read += 1

        result |= (byte & 0x7F) << shift
        shift += 7

        if (byte & 0x80) == 0:
            break

    return result, bytes_read

