def verify_knowledge_unit(self, knowledge_unit: Dict[str, Any]) -> Dict[str, Any]:
    """
    Verify a knowledge unit.

    Args:
        knowledge_unit: Knowledge unit to verify

    Returns:
        Verification results
    """
    # Extract content from knowledge unit
    content = knowledge_unit.get('content', '')
    if isinstance(content, dict):
        # Handle structured content
        content_str = str(content)
    else:
        # Handle text content
        content_str = str(content)

    # Verify the content as a statement
    is_verified, confidence, word_verification = self.verifier.verify_statement(content_str)

    # Determine verification status
    if confidence >= 0.8:
        status = 'verified'
    elif confidence >= 0.5:
        status = 'partially_verified'
    else:
        status = 'unverified'

    # Create verification result
    verification_result = {
        'status': status,
        'confidence': confidence,
        'word_verification_count': {
            'total': len(word_verification),
            'verified': sum(1 for v in word_verification.values() if v),
            'unverified': sum(1 for v in word_verification.values() if not v)
        },
        'source': 'truth_engine',
        'metadata': {
            'domain': knowledge_unit.get('domain', 'unknown'),
            'type': knowledge_unit.get('type', 'unknown')
        }
    }

    return verification_result

