# --- function 1: ChatLog.__init__ (method) lines 5-8 mode=ast ---
def __init__(self, storage_file="chatlog.json"):
    self.log = []
    self.storage_file = storage_file
    self.load_log()

# --- function 2: ChatLog.load_log (method) lines 10-16 mode=ast ---
def load_log(self):
    """ Load existing chat logs from file """
    try:
        with open(self.storage_file, "r") as f:
            self.log = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        self.log = []

# --- function 3: ChatLog.save_log (method) lines 18-21 mode=ast ---
def save_log(self):
    """ Save chat logs to file """
    with open(self.storage_file, "w") as f:
        json.dump(self.log, f, indent=4)

# --- function 4: ChatLog.add_entry (method) lines 23-36 mode=ast ---
def add_entry(self, role, content, context=None, subcontext=None, subsubcontext=None):
    """ Adds a new entry with hierarchical context and timestamps """
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    entry = {
        "timestamp": timestamp,
        "role": role,
        "content": content,
        "context": context or "",
        "subcontext": subcontext or "",
        "subsubcontext": subsubcontext or "",
        "changes": []
    }
    self.log.append(entry)
    self.save_log()

# --- function 5: ChatLog.add_change (method) lines 38-49 mode=ast ---
def add_change(self, entry_id, change_description):
    """ Adds a tracked change to an existing chat entry """
    if 0 <= entry_id < len(self.log):
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        change = {
            "timestamp": timestamp,
            "description": change_description
        }
        self.log[entry_id]["changes"].append(change)
        self.save_log()
    else:
        print("Error: Invalid entry ID")

# --- function 6: ChatLog.query_log (method) lines 51-59 mode=ast ---
def query_log(self, context=None, subcontext=None, subsubcontext=None):
    """ Retrieve chat history based on structured hierarchy """
    results = [
        entry for entry in self.log
        if (context is None or entry["context"] == context) and
           (subcontext is None or entry["subcontext"] == subcontext) and
           (subsubcontext is None or entry["subsubcontext"] == subsubcontext)
    ]
    return results


