# --- function 1: binary_to_frequency (function) lines 7-9 mode=ast ---
def binary_to_frequency(binary_code):
    """Converts binary code to a unique frequency in Hz."""
    return int(binary_code, 2) % 20000 + 100  # Ensures frequency is within 100Hz-20kHz

# --- function 2: process_json_file (function) lines 11-21 mode=ast ---
def process_json_file(input_path):
    """Reads a JSON dictionary file, assigns tones to words, and returns a new simplified dictionary."""
    with open(input_path, 'r', encoding='utf-8') as file:
        data = json.load(file)

    simplified_dict = {}
    for word, details in data.items():
        if "binary" in details:
            simplified_dict[word] = binary_to_frequency(details["binary"])

    return simplified_dict

