def _anchor_text_function(self, data: str, node: CascadeNode, config: Dict[str, Any]) -> Tuple[Any, float]:
    """Process text anchor data"""
    words = data.split()

    result = {
        'text': data,
        'word_count': len(words),
        'character_count': len(data),
        'average_word_length': sum(len(word) for word in words) / len(words) if words else 0,
        'anchor_type': 'text'
    }

    confidence = 0.7 if words else 0.3
    return result, confidence

