def _bloom_text_function(self, data: str, node: CascadeNode, config: Dict[str, Any]) -> Tuple[Any, float]:
    """Process text bloom data"""
    # Simple text analysis
    sentences = data.split('.')
    words = data.split()

    result = {
        'text': data,
        'sentence_count': len([s for s in sentences if s.strip()]),
        'word_count': len(words),
        'character_count': len(data),
        'bloom_type': 'text'
    }

    confidence = 0.6 if words else 0.2
    return result, confidence

# --- function 18: CascadeEngine._find_repeats (method) lines 434-442 mode=ast ---
def _find_repeats(self, sequence: str) -> List[str]:
    """Find repeated sequences"""
    repeats = []
    for length in range(2, min(6, len(sequence) // 2)):
        for i in range(len(sequence) - length):
            substring = sequence[i:i+length]
            if sequence.count(substring) > 1 and substring not in repeats:
                repeats.append(substring)
    return repeats

# --- function 19: CascadeEngine._find_gc_regions (method) lines 444-455 mode=ast ---
def _find_gc_regions(self, sequence: str) -> List[Tuple[int, int]]:
    """Find GC-rich regions"""
    gc_regions = []
    window_size = min(10, len(sequence) // 4)

    for i in range(len(sequence) - window_size + 1):
        window = sequence[i:i+window_size]
        gc_count = window.upper().count('G') + window.upper().count('C')
        if gc_count / window_size > 0.6:  # GC-rich threshold
            gc_regions.append((i, i + window_size))

    return gc_regions

# --- function 20: CascadeEngine._find_at_regions (method) lines 457-468 mode=ast ---
def _find_at_regions(self, sequence: str) -> List[Tuple[int, int]]:
    """Find AT-rich regions"""
    at_regions = []
    window_size = min(10, len(sequence) // 4)

    for i in range(len(sequence) - window_size + 1):
        window = sequence[i:i+window_size]
        at_count = window.upper().count('A') + window.upper().count('T')
        if at_count / window_size > 0.6:  # AT-rich threshold
            at_regions.append((i, i + window_size))

    return at_regions

