def _result_to_dict(self, result: CascadeResult) -> Dict[str, Any]:
    """Convert CascadeResult to dictionary"""
    return {
        'node_id': result.node_id,
        'node_type': result.node_type,
        'level': result.level,
        'position': result.position,
        'data': result.data,
        'processed_data': result.processed_data,
        'function_applied': result.function_applied,
        'confidence': result.confidence,
        'metadata': result.metadata
    }

