# --- function 5: HardwareValidator.detect_nvidia_gpus (method) lines 51-96 mode=ast ---
def detect_nvidia_gpus(self) -> List[Dict]:
    """Detect NVIDIA GPUs using nvidia-smi"""
    gpus = []
    try:
        result = subprocess.run(
            ["nvidia-smi", "--query-gpu=name,memory.total,driver_version", "--format=csv,noheader,nounits"],
            capture_output=True,
            text=True,
            timeout=10
        )

        if result.returncode == 0:
            for line in result.stdout.strip().split('\n'):
                if line.strip():
                    parts = [p.strip() for p in line.split(',')]
                    if len(parts) >= 3:
                        gpus.append({
                            "vendor": "NVIDIA",
                            "name": parts[0],
                            "memory_mb": int(parts[1]),
                            "driver_version": parts[2],
                            "backend": "cuda",
                            "detected_method": "nvidia-smi"
                        })
    except (subprocess.TimeoutExpired, subprocess.CalledProcessError, FileNotFoundError):
        pass

    # Fallback: Try PyTorch CUDA detection
    if not gpus:
        try:
            import torch
            if torch.cuda.is_available():
                for i in range(torch.cuda.device_count()):
                    props = torch.cuda.get_device_properties(i)
                    gpus.append({
                        "vendor": "NVIDIA",
                        "name": props.name,
                        "memory_mb": props.total_memory // (1024 * 1024),
                        "compute_capability": f"{props.major}.{props.minor}",
                        "backend": "cuda",
                        "detected_method": "pytorch"
                    })
        except ImportError:
            pass

    return gpus

# --- function 6: HardwareValidator.detect_amd_gpus (method) lines 98-144 mode=ast ---
def detect_amd_gpus(self) -> List[Dict]:
    """Detect AMD GPUs using rocm-smi or other methods"""
    gpus = []

    # Try rocm-smi
    try:
        result = subprocess.run(
            ["rocm-smi", "--showproductname", "--showmeminfo", "vram"],
            capture_output=True,
            text=True,
            timeout=10
        )

        if result.returncode == 0:
            # Parse rocm-smi output (simplified)
            lines = result.stdout.strip().split('\n')
            for line in lines:
                if "GPU" in line and ":" in line:
                    # Basic parsing - would need more sophisticated parsing for real use
                    gpus.append({
                        "vendor": "AMD",
                        "name": "AMD GPU (detected via rocm-smi)",
                        "backend": "rocm",
                        "detected_method": "rocm-smi"
                    })
                    break
    except (subprocess.TimeoutExpired, subprocess.CalledProcessError, FileNotFoundError):
        pass

    # Fallback: Try PyTorch ROCm detection
    if not gpus:
        try:
            import torch
            if torch.cuda.is_available():
                # Check if this is actually ROCm
                device_name = torch.cuda.get_device_name(0)
                if any(keyword in device_name.upper() for keyword in ["AMD", "RADEON", "RX"]):
                    gpus.append({
                        "vendor": "AMD",
                        "name": device_name,
                        "backend": "rocm",
                        "detected_method": "pytorch-rocm"
                    })
        except ImportError:
            pass

    return gpus

