def log(self, message, level='INFO'):
    if self._should_log(level):
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        log_entry = f"[{timestamp}] [{level}] {message}"

        with open(self.log_file, 'a') as f:
            f.write(log_entry + '\n')

        if level in ['ERROR', 'CRITICAL']:
            print(log_entry)

