def write_safe(log_file, data, max_retries=3):
    for attempt in range(max_retries):
        try:
            with open(log_file, "a", encoding="utf-8") as f:
                f.write(json.dumps(data, ensure_ascii=False, default=str) + "\n")
                f.flush()
            return True
        except Exception:
            time.sleep(0.05 * (attempt + 1))
    return False

