def __init__(self, db_path: str = "reaper_network.db"):
    self.db_path = db_path
    self.cognitive_anchors = self._initialize_cognitive_anchors()
    self.baseline_patterns = {}
    self.anomaly_memory = {}
    self.threat_thresholds = {
        'AUTHENTIC': 0.3,
        'SUSPICIOUS': 0.5,
        'THREAT': 0.7,
        'CRITICAL': 0.9
    }
    self._initialize_database()

# --- function 3: NetworkCognitiveAnalyzer._initialize_database (method) lines 88-141 mode=ast ---
def _initialize_database(self):
    """Initialize SQLite database for network analysis"""
    conn = sqlite3.connect(self.db_path)
    cursor = conn.cursor()

    # Network events table
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS network_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            timestamp TEXT NOT NULL,
            protocol TEXT,
            local_address TEXT,
            local_port INTEGER,
            remote_address TEXT,
            remote_port INTEGER,
            state TEXT,
            pid INTEGER,
            process_name TEXT,
            threat_level REAL,
            cognitive_coherence REAL,
            human_likelihood REAL,
            anomaly_score REAL
        )
    ''')

    # Process baselines table
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS process_baselines (
            process_name TEXT PRIMARY KEY,
            avg_connections INTEGER,
            common_ports TEXT,
            typical_protocols TEXT,
            baseline_established TIMESTAMP,
            last_updated TIMESTAMP
        )
    ''')

    # Anomaly memory table
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS anomaly_memory (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            remote_address TEXT,
            process_name TEXT,
            anomaly_type TEXT,
            first_seen TIMESTAMP,
            last_seen TIMESTAMP,
            occurrence_count INTEGER,
            severity_score REAL
        )
    ''')

    conn.commit()
    conn.close()
    logger.info("Database initialized successfully")

