def _loop(self) -> None:
    while self._running:
        try:
            events = fuse_session(self.session_dir)
            self._last_fuse_count = len(events)
        except Exception as exc:
            logger.error("FusionWatcher error: %s", exc)
        time.sleep(self.interval_sec)

