# --- function 1: get_engine (function) lines 43-51 mode=ast ---
def get_engine():
    """Get or create the WolfEngine singleton. Lazy-loaded, thread-safe."""
    global _engine
    if _engine is None:
        with _engine_lock:
            if _engine is None:
                from wolf_engine.core.engine import WolfEngine
                _engine = WolfEngine()
    return _engine

