# --- function 2: ForgeServiceRunner.run (method) lines 64-94 mode=ast ---
def run(self) -> None:
    """Start the ZMQ REP loop. Blocks until stop() is called."""
    ctx = zmq.Context()
    socket = ctx.socket(zmq.REP)
    socket.bind(self.bind_addr)
    socket.RCVTIMEO = 1000  # 1s poll for shutdown check
    self._running = True
    logger.info("Forge service listening on %s", self.bind_addr)

    try:
        while self._running:
            try:
                msg = socket.recv()
            except zmq.Again:
                continue  # Timeout, check _running flag

            try:
                action, payload = decode_request(msg)
                handler = self._handlers.get(action)
                if handler is None:
                    reply = encode_response("error", f"Unknown action: {action}")
                else:
                    reply = handler(payload)
            except Exception as exc:
                logger.error("Request handling error: %s", exc)
                reply = encode_response("error", str(exc))

            socket.send(reply)
    finally:
        socket.close()
        ctx.term()

# --- function 3: ForgeServiceRunner.stop (method) lines 96-98 mode=ast ---
def stop(self) -> None:
    """Signal the service to stop."""
    self._running = False

# --- function 4: ForgeServiceRunner.close (method) lines 100-103 mode=ast ---
def close(self) -> None:
    """Clean up resources."""
    self.sql_writer.close()
    self.sql_reader.close()

