def register(self, name: str, zmq_addr: str) -> None:
    """Register a service to monitor."""
    self.services[name] = ServiceStatus(name, zmq_addr, self.miss_threshold)

# --- function 8: HealthMonitor.check_one (method) lines 75-103 mode=ast ---
def check_one(self, name: str) -> bool:
    """Check a single service health. Returns True if healthy."""
    import zmq

    svc = self.services.get(name)
    if svc is None:
        return False

    ctx = zmq.Context.instance()
    sock = ctx.socket(zmq.REQ)
    sock.RCVTIMEO = 2000
    sock.SNDTIMEO = 2000
    sock.setsockopt(zmq.LINGER, 0)
    try:
        sock.connect(svc.addr)
        sock.send(encode_request("health"))
        reply = sock.recv()
        status, _ = decode_response(reply)
        if status == "ok":
            svc.record_success()
            return True
        else:
            svc.record_failure()
            return False
    except Exception:
        svc.record_failure()
        return False
    finally:
        sock.close()

# --- function 9: HealthMonitor.check_all (method) lines 105-111 mode=ast ---
def check_all(self) -> dict[str, dict]:
    """Check all registered services. Returns status dict."""
    results = {}
    for name in self.services:
        self.check_one(name)
        results[name] = self.services[name].to_dict()
    return results

# --- function 10: HealthMonitor.start (method) lines 113-117 mode=ast ---
def start(self) -> None:
    """Start background health monitoring thread."""
    self._running = True
    self._thread = threading.Thread(target=self._loop, daemon=True)
    self._thread.start()

# --- function 11: HealthMonitor.stop (method) lines 119-123 mode=ast ---
def stop(self) -> None:
    """Stop background monitoring."""
    self._running = False
    if self._thread:
        self._thread.join(timeout=self.interval_sec + 1)

# --- function 12: HealthMonitor._loop (method) lines 125-131 mode=ast ---
def _loop(self) -> None:
    while self._running:
        try:
            self.check_all()
        except Exception as exc:
            logger.error("Health check error: %s", exc)
        time.sleep(self.interval_sec)


