def _make_event(
    symbol_id: int,
    context_symbols: list[int] | None = None,
    session_id: str = "",
    pulse_id: int = 1,
) -> SymbolEvent:
    return SymbolEvent(
        event_id=str(uuid.uuid4()),
        session_id=session_id or str(uuid.uuid4()),
        pulse_id=pulse_id,
        symbol_id=symbol_id,
        context_symbols=context_symbols or [],
        category="core",
        priority=1,
    )

