# --- function 1: _response (function) lines 38-51 mode=ast ---
def _response(
    confidence: float = 0.5,
    consistency: float = 0.5,
    windows: int = 10,
    session_id: str = "sess_1",
    **kwargs,
) -> EngineResponse:
    return EngineResponse(
        session_id=session_id,
        confidence=confidence,
        avg_consistency=consistency,
        total_windows=windows,
        **kwargs,
    )

# --- function 2: _make_event (function) lines 54-61 mode=ast ---
def _make_event(sid: int, ctx: list[int] | None = None) -> SymbolEvent:
    return SymbolEvent(
        event_id=str(uuid.uuid4()),
        session_id="test",
        pulse_id=1,
        symbol_id=sid,
        context_symbols=ctx or [],
    )

# --- function 3: _make_events_with_context (function) lines 64-69 mode=ast ---
def _make_events_with_context(symbol_ids: list[int]) -> list[SymbolEvent]:
    events = []
    for i, sid in enumerate(symbol_ids):
        ctx = symbol_ids[max(0, i - 6): i] + symbol_ids[i + 1: i + 7]
        events.append(_make_event(sid, ctx))
    return events

