# --- function 29: TestReasoningService._start_service (method) lines 337-343 mode=ast ---
def _start_service(self, forge: ForgeMemory, port: int) -> ReasoningServiceRunner:
    addr = f"tcp://127.0.0.1:{port}"
    svc = ReasoningServiceRunner(forge, bind_addr=f"tcp://*:{port}")
    t = threading.Thread(target=svc.run, daemon=True)
    t.start()
    time.sleep(0.3)
    return svc

# --- function 30: TestReasoningService._zmq_request (method) lines 345-357 mode=ast ---
def _zmq_request(self, port: int, action: str, payload: dict | None = None) -> tuple[str, dict]:
    ctx = zmq.Context.instance()
    sock = ctx.socket(zmq.REQ)
    sock.RCVTIMEO = 5000
    sock.SNDTIMEO = 2000
    sock.setsockopt(zmq.LINGER, 0)
    try:
        sock.connect(f"tcp://127.0.0.1:{port}")
        sock.send(encode_request(action, payload or {}))
        raw = sock.recv()
        return decode_response(raw)
    finally:
        sock.close()

