# --- function 36: TestOrchestrator._build_forge (method) lines 339-344 mode=ast ---
def _build_forge(self, ids: list[int]) -> ForgeMemory:
    forge = ForgeMemory(window_size=10000)
    events = _make_events_with_context(ids)
    for e in events:
        forge.ingest(e)
    return forge

