def __init__(self, **kwargs):
    super().__init__(**kwargs)
    self._counter = 0

# --- function 17: _DummyWorker.collect (method) lines 182-184 mode=ast ---
def collect(self):
    self._counter += 1
    return [{"event_type": "dummy_tick", "count": self._counter}]

