def _build_connected_forge(self) -> ForgeMemory:
    """Build a Forge with clear co-occurrence chains: 1→2→3→4→5."""
    forge = ForgeMemory(window_size=5000)
    for _ in range(20):
        for i in range(1, 6):
            forge.ingest(_make_event(i, [i - 1, i + 1] if i > 1 else [i + 1]))
    return forge

